const CAT_1={"id":1,"n":"Школа","sub":"Базові навички","e":"🎒","col":"c1","blocks":[{"n":"📖 Базове читання, робота з текстом та пам'ять","e":"","cards":[[1,"Метод повторення прочитаного за 1 хвилину","<div class=\"rule-note\">🧠 <b>Метод Free Recall:</b> одразу після читання — закрий книгу і розкажи головну думку своїми словами. Дослідження показують: активне відтворення суттєво ефективніше за повторне читання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>📖 Прочитай параграф повністю</b><br>Не поспішай, читай уважно до кінця. Не роби нотатки під час читання.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>📕 Закрий книгу</b><br>Не підглядай! Це найважливіший момент методу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>🗣️ Розкажи основне за 60 секунд</b><br>Вголос або подумки. Своїми словами — не дослівно.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>✅ Відкрий і перевір</b><br>Що пропустив — то і є прогалини. Перечитай лише ці місця.</div></div><div class=\"final-note\">💡 <b>Приклад:</b> Прочитав § про фотосинтез → кажеш: «Рослина поглинає світло та CO₂, виробляє кисень і глюкозу» → відкриваєш і доповнюєш деталі.</div>"],[2,"Пошук головного слова у реченні","<div class=\"rule-note\">🔑 <b>Головне правило:</b> Підмет (хто? що?) + Присудок (що робить?) = суть будь-якого речення. Знайди їх — зрозумієш зміст навіть складного тексту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запитай «Про кого/що речення?»</b><br>Слово, яке відповідає — це <b>підмет</b>. Підкресли одною рискою.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Запитай «Що він робить/є?»</b><br>Слово, яке відповідає — це <b>присудок</b>. Підкресли двома рисками.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Решта — другорядні члени</b><br>Їх можна опустити — суть речення залишиться зрозумілою.</div></div><div class=\"final-note\">📌 «Старий дуб росте на узліссі.» → <b>Дуб</b> (підмет) + <b>росте</b> (присудок). Навіть без «старий» і «на узліссі» суть зрозуміла.</div>"],[3,"Правило триразового прочитання","<div class=\"rule-note\">📖 <b>Головне правило:</b> Три читання — три різні цілі. Не поспішай при першому!</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>🏃 Перший раз — Огляд</b><br>Читай швидко, не зупиняйся. Мета: загальне уявлення про тему. Прочитай заголовки, виділений текст, перший і останній абзаци.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>✏️ Другий раз — Розуміння</b><br>Читай повільно, з олівцем. Підкреслюй незрозуміле, виділяй головне, пиши питання на полях.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>🎯 Третій раз — Деталі</b><br>Повертайся тільки до підкресленого та ключових абзаців. Відповідай на свої питання з полів.</div></div><div class=\"final-note\">⏱ <b>Час:</b> 1-е читання — швидко (50% часу); 2-е — детально (35%); 3-є — вибірково (15%)</div>"],[4,"Виділення незнайомих слів","<div class=\"rule-note\">📚 <b>Словник читача</b> — зошит або картки для нових слів. Формат запису: слово — значення — приклад з тексту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Під час читання підкреслюй незнайомі слова</b><br>Не зупиняйся — спочатку прочитай абзац до кінця.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Після абзацу виписуй їх</b><br>Одне слово — один рядок. Залиш місце для значення.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знайди значення</b><br>У словнику або за контекстом (що підказує речення навколо?).</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Запиши приклад</b><br>Коротке речення зі словом. Це закріплює в пам'яті краще за визначення.</div></div><div class=\"final-note\">📅 Переглядай словник раз на тиждень — так слова переходять у довготривалу пам'ять. Приклад: «архаїзм» — застаріле слово — «хатина» (замість «будинок»).</div>"],[5,"Складання малюнкового плану","<div class=\"rule-note\">🎨 <b>Малюнковий план</b> — послідовність простих піктограм замість текстового конспекту. Мозок запам'ятовує зображення краще, ніж слова.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Поділи текст на 4–6 ключових моментів</b><br>Великий текст → кілька міні-сцен або подій.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Для кожного намалюй просту схему</b><br>10–15 секунд на малюнок. Не треба гарно — треба зрозуміло.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перекажи за малюнками</b><br>Закрий текст. Розповідай, дивлячись тільки на піктограми.</div></div><div class=\"final-note\">🦊 «Лисиця і журавель»: 🦊→🍲 (лисиця пригощає) → 🦩→🏺 (журавель відповідає) → 😤 (обидва голодні). Або кругообіг: ☁️→💧→🌊→♨️→☁️</div>"],[6,"Розбиття тексту на смислові частини","<div class=\"rule-note\">📑 <b>Мікрозаголовки</b> — великий текст легше запам'ятати, якщо розділити на 3–5 блоків і дати кожному назву.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай абзац або розділ</b><br>Не переривайся на нотатки під час читання.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Запитай: «Про що цей фрагмент?»</b><br>Одне-два слова, що передають суть.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запиши назву на полі</b><br>Коротко: «Початок», «Перший бій», «Перелом» тощо.</div></div><div class=\"final-note\">📖 Параграф про Другу світову: «Початок» / «Перші бої» / «Перелом» / «Перемога». При відповіді на уроці — розповідаєш по блоках, нічого не забуваєш.</div>"],[7,"Техніка «Запитання до тексту»","<div class=\"rule-note\">❓ <b>Активне читання</b> — ставити питання ДО, ПІД ЧАС і ПІСЛЯ читання. Мозок шукає відповіді та краще запам'ятовує.</div><div class=\"step c2\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>⬅️ ДО читання</b><br>«Що я вже знаю про цю тему?» Переглянь заголовок, сформулюй 1–2 питання, відповіді на які шукатимеш.</div></div><div class=\"step c1\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>📖 ПІД ЧАС читання</b><br>До кожного абзацу: <b>Хто? Що? Де? Коли? Чому? Як?</b> Записуй короткі відповіді на полях.</div></div><div class=\"step c4\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>➡️ ПІСЛЯ читання</b><br>«Що нового я дізнався?» «Що залишилось незрозумілим?» Запиши 1 головну думку тексту своїми словами.</div></div>"],[8,"Як запам'ятовувати вірші за ассоціаціями","<div class=\"rule-note\">🎬 <b>Метод образних зв'язків:</b> кожному рядку вірша — яскравий образ-картинка. Мозок запам'ятовує дивні, рухливі образи краще ніж слова.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай рядок вголос</b><br>Відчуй ритм і настрій. Вимовляй виразно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Уяви живу, яскраву сцену</b><br>Образ має бути незвичним і рухливим. Чим смішніший — тим краще!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Зв'яжи образи у «мультфільм»</b><br>Кожна наступна картинка починається там, де закінчилась попередня.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перекажи вірш за образами</b><br>Дивись у «фільм» у голові — слова прийдуть самі.</div></div><div class=\"final-note\">📌 «Реве та стогне Дніпр широкий» → велика блакитна річка плаче і кричить, б'ючи хвилями в кручі. Незвично → запам'ятається!</div>"],[9,"Використання кольорових маркерів","<div class=\"rule-note\">🖊️ <b>Одна система — для всіх предметів.</b> Не змінюй кольори — тоді мозок читає їх автоматично!</div><div class=\"step c1\"><div class=\"step-num\">🟡</div><div class=\"step-text\"><b>Жовтий — факти та головні твердження</b><br>Основні думки параграфа, висновки, ключові ствердження.</div></div><div class=\"step c3\"><div class=\"step-num\">🟢</div><div class=\"step-text\"><b>Зелений — числа та дати</b><br>Роки, числові дані, імена, географічні назви.</div></div><div class=\"step c2\"><div class=\"step-num\">🩷</div><div class=\"step-text\"><b>Рожевий — терміни</b><br>Нові наукові поняття та слова з визначенням.</div></div><div class=\"step c4\"><div class=\"step-num\">✏️</div><div class=\"step-text\"><b>Олівець — власні думки</b><br>Питання до тексту, сумніви, зв'язки з іншими темами.</div></div><div class=\"final-note\">⚠️ <b>Не виділяй більше 20–30% тексту!</b> Якщо виділено все — не виділено нічого.</div>"],[10,"Техніка складання простих шпаргалок","<div class=\"rule-note\">✏️ <b>Шпаргалка — не для списування, а для запам'ятовування!</b> Писання фіксує матеріал на 40% краще, ніж повторне читання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Пиши тільки ключові слова</b><br>НЕ переписуй підручник — тільки суть! Скорочення та символи вітаються.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Один аркуш = одна тема</b><br>Не мішай теми. Маленький аркуш — більше зусиль відбору.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Пиши дрібно</b><br>Мозок вмикає «режим відбору» важливого — і запам'ятовує краще.</div></div><div class=\"final-note\">📐 Формули площ: S□=a² | S▭=a·b | S△=½a·h — три рядки замість параграфа. Або дати: 1654→Переяслав | 1709→Полтава.</div>"],[11,"Метод «Асоціативний кущ»","<div class=\"rule-note\">🌳 <b>Асоціативний кущ</b> (Mind Map) — візуальний конспект замість суцільного тексту. Мозок любить структуру і зв'язки.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Центр</b><br>Напиши головне поняття у центрі аркуша. Наприклад: <b>ВОДА</b>. Обведи кружечком.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Гілки 1-го рівня</b><br>5–6 великих тем навколо центру: властивості / стани / де є / для чого / приклади. З'єднай лініями.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Гілки 2-го рівня</b><br>Від кожної теми — 2–3 конкретних факти або приклади. Коротко, 1–3 слова.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Зв'язки</b><br>Зв'яжи стрілками споріднені поняття з різних гілок. Добав кольори та малюнки!</div></div>"],[12,"Переказ тексту від імені іншого персонажа","<div class=\"rule-note\">🎭 <b>Переказ від першої особи</b> — розповідь подій, стаючи одним із героїв. Поглиблює розуміння мотивів і змушує думати, а не заучувати.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай текст повністю</b><br>Зрозумій загальний хід подій та мотиви персонажів.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Обери будь-якого персонажа</b><br>Не обов'язково головного — другорядний навіть цікавіше!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перекажи його очима</b><br>Що він бачив? Що відчував? Що думав? Чому так вчинив?</div></div><div class=\"final-note\">🦊 «Колобок» від Лисиці: «Іду я лісом, голодна. Раптом чую — хтось весело співає. Дивлюсь — круглий колобок котиться. Думаю: ось і обід! Треба схитрувати...» Такий переказ не забудеш!</div>"],[13,"Пошук причинно-наслідкових зв'язків","<div class=\"rule-note\">⛓️ <b>Головне правило:</b> Розуміти текст = розуміти ЧОМУ відбуваються події. Схема: Причина → Подія → Наслідок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди важливу подію</b><br>Запиши її в центрі ланцюжка.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайди причину</b><br>Запитай: «Чому це сталося? Що цьому передувало?»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знайди наслідок</b><br>Запитай: «Що через це трапилося далі? До чого це призвело?»</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Запиши ланцюжок зі стрілками</b><br>Причина → Подія → Наслідок → (новий наслідок…)</div></div><div class=\"final-note\">☀️ Посуха → 🌾 Неврожай → 😔 Голод → 🏙️ Люди вирушили в місто. Особливо корисно для <b>історії, біології та географії!</b></div>"],[14,"Робота з первинними правилами з мови","<div class=\"rule-note\">🔤 <b>Алгоритм перевірки орфограми</b> — покрокова процедура вибору правильного написання. Завжди однаковий — для будь-якого правила.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач тип орфограми</b><br>Ненаголошена голосна? Апостроф? Сумнівна приголосна? Велика літера?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пригадай правило</b><br>Якщо не пам'ятаєш — підкресли слово і повернись після закінчення роботи.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Підбери перевірочне слово</b><br>(Якщо правило це передбачає.) Поставь голосну під наголос.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Запиши правильний варіант</b><br>Перечитай речення — чи звучить природно?</div></div><div class=\"final-note\">✅ «зем..я» → тип: пом'якшення → правило: після приголосної перед «я» пишемо «ь» → «земля» ✓. Якщо сумніваєшся — підкресли і повернись пізніше.</div>"],[15,"Як вчити складносурядні та складнопідрядні речення","<div class=\"rule-note\">📐 <b>ССР</b> — рівноправні частини (і/а/але/або). <b>СПР</b> — є залежна частина, яка відповідає на питання (що/коли/бо/якщо).</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди всі граматичні основи</b><br>Підмет + Присудок у кожній частині. Скільки основ — стільки частин.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Визнач сполучник між частинами</b><br>Яке слово з'єднує частини речення?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Визнач тип речення</b><br><b>і / а / але / або</b> → ССР (рівноправні). <b>що / коли / бо / якщо / де</b> → СПР (є залежна).</div></div><div class=\"final-note\">📌 ССР: «Сонце зайшло, і стало темно.» СПР: «Я знаю, що ти прийдеш» — <i>знаю</i> (головна) + <i>що ти прийдеш</i> (залежна, відповідає на «що?»).</div>"],[16,"Метод інтервального повторення для школи","<div class=\"rule-note\">🧠 <b>Інтервальне повторення:</b> без закріплення матеріал поступово згасає в пам'яті. Регулярні короткі повторення у правильний час — найефективніший спосіб утримати знання надовго.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>🕐 Відразу</b> — після вивчення<br>Перекажи або запиши основне своїми словами. 2–3 хвилини.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>⏱ Через 20 хвилин</b><br>Коротко повтори ключові пункти без підручника. 1 хвилина.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>🌙 Через 1 день</b><br>Перекажи тему вголос або другу. Якщо забув — подивись і повтори ще раз.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>📅 Через 7 та 30 днів</b><br>Коротке повторення перед сном або вранці. 2–3 хвилини — і матеріал залишиться назавжди.</div></div><div class=\"final-note\">💡 Принцип: кожне наступне повторення відтерміновується трохи більше. Так мозок поступово переносить матеріал у довготривалу пам'ять без зубріння.</div>"],[17,"Як запам'ятати історичні дати","<div class=\"rule-note\">🧲 <b>Метод «прив'язки до особистого»</b> — пов'язати дату з тим, що вже знаєш і добре пам'ятаєш. Нове чіпляється за знайоме!</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запиши дату і подію</b><br>Наприклад: 1654 — Переяславська рада.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайди зв'язок із відомим числом</b><br>Схожість із днем народження, номером будинку, роком з іншої теми.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Або придумай вірш-лічилку</b><br>Коротку фразу, де є цифри дати. Ритм допомагає!</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Або створи образ</b><br>Дивний, смішний або яскравий — мозок любить незвичайне!</div></div><div class=\"final-note\">🗡️ 1654 (Переяслав) → «1-6-5-4 — козак договір підписав». 1709 (Полтава) → «Сімнадцятий вік, нуль дев'ять — Карл утікав». Вигадуй своє!</div>"],[18,"Робота з географічною картою","<div class=\"rule-note\">🗺️ <b>Карта — мова символів.</b> Знаючи координати та умовні знаки, знайдеш будь-який об'єкт на планеті.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач масштаб</b><br>Що означає 1 см на цій карті? (написано у куті).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайди широту</b><br>Горизонтальні лінії (паралелі). 0° — екватор, 90° — полюс.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знайди довготу</b><br>Вертикальні лінії (меридіани). 0° — Гринвіч, 180° — антимеридіан.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Знайди об'єкт та перевір знаки</b><br>Шукай у перетині координат. Умовні знаки — у легенді карти.</div></div><div class=\"final-note\">📍 Київ — приблизно 50°N, 30°E. Знаходиш горизонталь 50° і вертикаль 30° → їх перетин вказує на Київ.</div>"],[19,"Правило «Прочитав — поясни другу»","<div class=\"rule-note\">🧑‍🏫 <b>Метод Фейнмана:</b> якщо можеш пояснити просто — ти насправді розумієш матеріал. Пояснення виявляє прогалини краще за будь-який тест.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Вивчи тему за підручником</b><br>Читай уважно, роби нотатки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Закрий підручник</b><br>Не підглядай під час пояснення!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Поясни уявному другу з молодшого класу</b><br>Без складних слів. Просто, як для 10-річного.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Там, де застряг — повернись</b><br>Прогалина знайдена! Перечитай лише цю частину і повтори крок 3.</div></div><div class=\"final-note\">💡 «Молекула»: «Уяви, що всі речі зроблені з дуже маленьких кульок, які весь час рухаються. Вода — це кульки H₂O». Не можеш пояснити просто — ще не розумієш.</div>"],[20,"Як виділити головну думку казкового сюжету","<div class=\"rule-note\">💡 <b>Головна думка (мораль)</b> — урок, який автор хотів передати. Прихована в кінці або у вчинках персонажів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Хто герой і що він зробив?</b><br>Опиши дію головного героя одним реченням.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Яким був результат?</b><br>Добрий чи поганий? Чого він досяг або чого не досяг?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>«Що автор хотів нас навчити?»</b><br>Яку пораду дає ця казка? Подумай від зворотнього.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Сформулюй одним реченням</b><br>«Не варто...», «Завжди...», «Якщо..., то...»</div></div><div class=\"final-note\">🦊 «Лисиця та виноград» Езопа: Лисиця не дістала виноград і сказала, що він кислий. Мораль: «Легко лаяти те, чого не можеш досягти».</div>"],[21,"Створення карток з термінами","<div class=\"rule-note\">🃏 <b>Флеш-картки</b> — двосторонні картки для активного самоповторення. Дослідження підтверджують: активне відтворення (тест себе) значно ефективніше за пасивне перечитування.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Нарізай картки з паперу</b><br>Або використовуй стікери. <b>Лицьова сторона:</b> термін або питання.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Зворотна: визначення + приклад</b><br>Коротко. Одна картка — одне поняття.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Переглядай щодня по 10 хвилин</b><br>Відкладай «знаю» від «не знаю». Тільки чесно!</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Наступного дня — тільки «не знаю»</b><br>Повторюй до тих пір, поки вся стопка стане «знаю».</div></div><div class=\"final-note\">📋 Лицьова: «МЕТАФОРА — це...?» Зворотна: «Перенесення назви на основі схожості. Приклади: золоті руки, море сміху, кам'яне серце».</div>"],[22,"Техніка швидкого перегляду змісту","<div class=\"rule-note\">🔍 <b>Огляд перед читанням</b> — 2–3 хвилини підготовки допомагають краще зрозуміти і запам'ятати текст: мозок знає, що шукати.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>📌 Заголовки</b><br>Прочитай заголовок і всі підзаголовки. Склади уявлення про структуру тексту.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>🖼️ Ілюстрації</b><br>Переглянь малюнки, схеми, таблиці та їх підписи — вони містять ключову інформацію.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>📝 Перший і останній абзаци</b><br>Прочитай їх повністю — зазвичай вони містять головну думку і висновки.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>❓ Своє питання</b><br>Сформулюй 1–2 питання, відповіді на які шукатимеш при читанні. Це вмикає «цілеспрямоване читання».</div></div><div class=\"final-note\">💡 Цей підхід схожий на перегляд трейлера перед фільмом: мозок будує «схему очікування» і активно шукає відповіді під час читання.</div>"],[23,"Правильне виконання вправ на підстановку","<div class=\"rule-note\">📝 <b>Вправа на підстановку</b> — вибір правильного варіанта (букви, слова, форми) на основі правила та контексту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай все речення до кінця</b><br>Ніколи не заповнюй пропуск, не прочитавши речення повністю!</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Визнач, яке правило тут діє</b><br>Відмінок? Час дієслова? Написання? Визнач тип задачі.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Застосуй правило</b><br>Перебери варіанти, залиш той, що відповідає правилу.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перечитай речення зі своєю відповіддю</b><br>Чи звучить природно? Вухо теж підказує!</div></div><div class=\"final-note\">✅ «Він прийшов до...(клас/класу/класові)» → «прийшов до» = родовий відмінок (куди?) → «класу» ✓. Перечитуєш: «Він прийшов до класу» — правильно.</div>"],[24,"Як вести шкільний словник з іноземної мови","<div class=\"rule-note\">🌍 <b>Словник іноземних слів з чотирма колонками:</b> слово | транскрипція | переклад | приклад. Четверта колонка — найважливіша!</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Поділи сторінку на 4 колонки</b><br>Слово | Транскрипція | Переклад | Приклад у реченні.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Вноси кожне нове слово одразу після уроку</b><br>Не відкладай — за день забудеш половину!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Раз на тиждень — самоперевірка</b><br>Закривай колонку перекладу і перекладай за пам'яттю.</div></div><div class=\"final-note\">📖 | dog | [dɒɡ] | собака | My dog runs fast. | Лайфхак: роби тематичні розділи («Тварини», «Числа», «Дім») — так знаходиш слова швидше.</div>"],[25,"Самоперевірка після написання тексту","<div class=\"rule-note\">✅ <b>Три кроки самоперевірки:</b> читання вголос → перевірка розділових знаків → читання з кінця.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Читай вголос</b><br>Вухо вловлює помилки, які очей пропускає: пропущені слова, незграбні фрази.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перевір розділові знаки</b><br>Пройдись по кожному реченню: де крапка? кома? де потрібний знак питання?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Читай від останнього речення до першого</b><br>Мозок не «вгадує» слова на автоматі → знаходиш помилки правопису.</div></div><div class=\"final-note\">📌 Написав твір → читаєш вголос → «і я пішов до магазин» → вухо відчуває: «до магазину!» → виправляєш. Займає 3–5 хвилин, рятує від прикрих помилок.</div>"],[26,"Механізм швидкого вивчення вірша","<div class=\"rule-note\">⚡ <b>Головне правило:</b> Не вчи вірш цілком! Одна строфа за раз. ⏱ <b>Орієнтир:</b> 5–7 хвилин на одну строфу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>🎬 «Мультик» (1хв)</b><br>• Прочитай строфу вголос.<br>• Уяви в голові: що там відбувається? Намалюй у думках картинку!<br>• <b>Ціль:</b> Запам'ятай не слова, а саму пригоду!</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>📄 «Шифр» (1хв)</b><br>• Запиши на аркуші тільки ПЕРШІ ЛІТЕРИ кожного слова.<br>• Приклад: Р д р м б… (замість «Реве та стогне…»)<br>• <b>Чому це працює:</b> Мозок любить розгадувати загадки!</div></div><div class=\"step c4\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>👐 «Жести» (1хв)</b><br>• Придумай для кожного рядка рух чи жест ручкою.<br>• <b>Ціль:</b> Зв'язати слово з дією — так легше запам'ятати!</div></div><div class=\"step c3\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>❄️ «Снігова куля» (2–3хв)</b><br>Сховай текст! Дивись тільки на ШИФР із літер:<br>1. Розкажи Рядок 1 (+ жест).<br>2. Розкажи Рядок 2 (+ жест). З'єднай: Рядок 1 + Рядок 2.<br>3. Розкажи Рядок 3 (+ жест). З'єднай: Рядок 1 + 2 + 3.<br>4. Розкажи Рядок 4 (+ жест). Повтори ВСЮ СТРОФУ!</div></div><div class=\"step c1\"><div class=\"step-num\">5</div><div class=\"step-text\"><b>✅ Критерій «Готово»</b><br>🔴 Зупинись! Переходь до наступної строфи тільки якщо:<br>• Ти розповів цю строфу за шифром БЕЗ ПОМИЛОК 3 рази поспіль.</div></div><div class=\"final-note\">🚀 <b>Фінальний етап — «Впяти» у пам'ять:</b><br>Коли всі строфи вивчені — з'єднай їх разом. Повтори вірш:<br>⏱ Через 20 хвилин &nbsp;|&nbsp; 🌙 Увечері перед сном (перенесе у довгу пам'ять) &nbsp;|&nbsp; ☀️ Вранці (1–2 рази, щоб закріпити)</div>"]]},{"n":"📐 Базова математика та логіка","e":"","cards":[[27,"Заучування таблиці множення через візуалізацію","<div class=\"rule-note\">📊 <b>Таблиця Піфагора</b> — квадрат 10×10, де рядки і стовпці — множники, клітинки — добутки. Візуальна пам'ять запам'ятовує числові зв'язки краще за зубріння.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Роздрукуй або намалюй таблицю Піфагора 10×10</b><br>Постав на стіл або повісь на стіну — переглядай щодня.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Вчи діагональ першою</b><br>Квадрати: 1×1=1, 2×2=4, 3×3=9, 4×4=16… — опорні числа.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Вчи рядками: один рядок на день</b><br>Перевіряй в зворотньому порядку (8×7, 7×7, 6×7…).</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Грай у флеш-картки</b><br>Перетасуй 20 карток з прикладами (7×8=?) і відповідями. Час — до 2 сек на картку.</div></div><div class=\"final-note\">💡 Лайфхак для 9: 9×N = (10×N)−N. Наприклад: 9×7 = 70−7 = 63. Перевірка: сума цифр добутку завжди = 9: 6+3=9 ✓</div>"],[28,"Розкладання складних задач на прості дії","<div class=\"rule-note\">🔪 <b>Декомпозиція</b> — будь-яка складна задача розпадається на 2–4 прості кроки. Вирішуй послідовно — і велике стає легким.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай умову і запитай: «Що треба знайти?»</b><br>Підкресли або запиши кінцеву мету.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Запиши «Дано»: що відоме, що невідоме</b><br>Схема або таблиця замість тексту.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Визнач: «Що треба знати ПЕРШЕ?»</b><br>Розбий на підзадачі — від відомого до невідомого.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Вирішуй підзадачі по порядку</b><br>Записуй проміжні результати — вони знадобляться.</div></div><div class=\"final-note\">📌 «Потяг їхав 3 год зі швидкістю 80 км/год. Скільки? Чи вистачить 200 км?» → (1) S=80×3=240 км → (2) 240>200 → вистачить ✓</div>"],[29,"Перевірка математичних дій зворотним шляхом","<div class=\"rule-note\">🔄 <b>Правило оберненої дії:</b> кожна математична операція має обернену. Перевіряй відповідь — і помилки зникнуть.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач обернену дію</b><br>+ ↔ − (додавання ↔ віднімання). × ↔ ÷ (множення ↔ ділення).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Підстав відповідь назад у вираз</b><br>Використай обернену дію щодо отриманого результату.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Порівняй з початковим числом</b><br>Мають збігатись — якщо ні, десь помилка.</div></div><div class=\"final-note\">✅ 48÷6=8 → перевірка: 8×6=48 ✓. 15−7=8 → перевірка: 8+7=15 ✓. 12×5=60 → перевірка: 60÷5=12 ✓. Завжди перевіряй!</div>"],[30,"Робота з геометричними фігурами","<div class=\"rule-note\">📐 <b>Метод розбиття:</b> складну фігуру — розбий на прості. Площа складного = сума площ частин. Або: велика фігура мінус вирізане.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розглянь фігуру і знайди прості форми в ній</b><br>Прямокутники, квадрати, трикутники — з яких вона складається?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Намалюй лінії розбиття (або добудуй до прямокутника)</b><br>Добудова: повний прямокутник − маленький = потрібна фігура.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Обчисли площу кожної частини за формулою</b><br>S□=a², S▭=a×b, S△=½×a×h</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Склади (або відніми) результати</b><br>Запиши повний хід обчислення.</div></div><div class=\"final-note\">📏 П-подібна фігура: добудуй до прямокутника 6×5=30 − вирізане 2×3=6 → S=24 см². Завжди малюй схему!</div>"],[31,"Як розв'язувати текстові задачі на рух","<div class=\"rule-note\">🚂 <b>Три кити задач на рух:</b> Відстань = Швидкість × Час (S = v × t). Знаєш два — знайдеш третє.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запиши «Дано»: S, v, t — що відоме, що невідоме</b><br>Використовуй стандартні позначення.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Намалюй схему руху</b><br>→[A]——S——[B]→, позначте швидкості, час, напрямки.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Вибери формулу</b><br>S=v·t (знайти відстань). v=S÷t (знайти швидкість). t=S÷v (знайти час).</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Підстав числа, обчисли, перевір одиниці</b><br>км/год або м/с — не мішай! Перевір оберненою дією.</div></div><div class=\"final-note\">🚗 Два авто назустріч: v₁=60, v₂=40, S=250 км. t=250÷(60+40)=250÷100=2.5 год. Одному напрямку: v_відн=v₁−v₂.</div>"],[32,"Округлення чисел для швидкого обчислення","<div class=\"rule-note\">🎯 <b>Правило округлення:</b> якщо цифра після потрібного розряду ≥ 5 → округлюй вгору, < 5 → залишай як є (заміни наступні цифри нулями).</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач, до якого розряду треба округлити</b><br>До десятків, сотень, тисяч — залежно від задачі.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Подивись на цифру ПРАВОРУЧ від нього</b><br>Це «контрольна» цифра — вона вирішує.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>≥ 5 → збільш на 1; < 5 → залиш без змін</b><br>Усі цифри праворуч заміни нулями.</div></div><div class=\"final-note\">📌 347 до десятків: цифра 7≥5 → 350. 342 до десятків: цифра 2<5 → 340. Корисно для перевірки: 48×52 ≈ 50×50=2500 — близько до точного 2496!</div>"],[33,"Робота з дробами","<div class=\"rule-note\">🍕 <b>Дріб = частина від цілого.</b> Щоб порівняти або додати дроби — потрібен спільний знаменник (однакові «порції»).</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Склади/відніми дроби</b><br>Зведи до спільного знаменника → склади/відніми чисельники → скороти якщо можна.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перемнож дроби</b><br>Чисельник × чисельник, знаменник × знаменник → скороти результат.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Поділи дроби</b><br>Перший × обернений другого (переверни другий дріб і перемнож).</div></div><div class=\"final-note\">📐 1/2 + 1/3 = 3/6 + 2/6 = 5/6. 2/3 × 3/4 = 6/12 = 1/2. 2/3 ÷ 4/5 = 2/3 × 5/4 = 10/12 = 5/6. Завжди скорочуй!</div>"],[34,"Закони додавання та множення","<div class=\"rule-note\">⚖️ <b>Три закони</b> — інструменти спрощення обчислень. Знаєш їх — рахуєш швидко і без помилок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Переставний: a+b=b+a; a×b=b×a</b><br>Від перестановки доданків/множників сума/добуток не змінюється.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Сполучний: (a+b)+c = a+(b+c)</b><br>Збирай зручні пари: 7+13+6 = (7+13)+6 = 20+6 = 26.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Розподільний: a×(b+c) = a×b + a×c</b><br>Розклади складне: 7×12 = 7×10 + 7×2 = 70+14 = 84.</div></div><div class=\"final-note\">💡 25×4=100 (легше ніж 4×25). 99×7 = (100−1)×7 = 700−7 = 693. 125×8 = 1000. Розпізнавай «зручні» пари!</div>"],[35,"Як правильно будувати координатну пряму","<div class=\"rule-note\">📏 <b>Координатна пряма</b> — числова вісь з початком відліку (0), одиничним відрізком і двома напрямками: + праворуч, − ліворуч.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Проведи горизонтальну пряму, постав стрілку праворуч</b><br>Стрілка показує напрямок зростання чисел.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Позначte точку 0 (початок відліку)</b><br>Трохи лівіше середини аркуша — щоб помістились від'ємні числа.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відміряй однакові відрізки — одиничний відрізок</b><br>1 клітинка або 1 см — головне однаково!</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Поставте числа праворуч (+) і ліворуч (−)</b><br>Відмічай точки: 3 кроки праворуч = точка +3, ліворуч = −3.</div></div><div class=\"final-note\">📍 Точка A(−3): 3 кроки ліворуч від 0. Відстань між A(−3) і B(5): |5−(−3)|=|5+3|=8 одиниць.</div>"],[36,"Алгоритм розв'язання простих рівнянь","<div class=\"rule-note\">⚖️ <b>Рівняння — терези:</b> будь-яка дія з одного боку — те саме роби з іншого. Мета: залишити <b>x</b> одного на одній стороні.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>x + a = b → x = b − a</b><br>x − a = b → x = b + a. <i>Переносимо доданок на інший бік зі зміною знака.</i></div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>x × a = b → x = b ÷ a</b><br>x ÷ a = b → x = b × a. <i>Переносимо множник/дільник оберненою дією.</i></div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Виконай обчислення, знайди x</b><br>Запиши чисте рівняння x = …</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перевірка: підстав x назад у рівняння</b><br>Якщо ліва частина = правій — відповідь правильна ✓</div></div><div class=\"final-note\">✅ x+7=15 → x=15−7=8. Перевірка: 8+7=15 ✓. 3x=24 → x=24÷3=8. Перевірка: 3×8=24 ✓. 2x−5=11 → 2x=16 → x=8. ✓</div>"],[37,"Робота з відсотками","<div class=\"rule-note\">💯 <b>1% = 1/100 частина від числа.</b> Три типи задач: знайти %, знайти частину, знайти ціле.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди % від числа</b><br>N × p ÷ 100. Або: N × 0.p (наприклад, 20% = 0.2).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайди ціле, якщо відома частина і %</b><br>(Частина ÷ p) × 100. Або: Частина ÷ 0.p.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Збільш/зменш на %</b><br>Збільшити: N × (1 + p/100). Зменшити: N × (1 − p/100).</div></div><div class=\"final-note\">📌 20% від 350: 350×0.2=70. Ціна з 15% знижкою: 400×0.85=340 грн. Лайфхак: 10% — відкинь останню цифру: 10% від 230 = 23. 15% = 10%+5%.</div>"],[38,"Як читати математичні знаки та дужки","<div class=\"rule-note\">🔢 <b>Пріоритет дій:</b> (1) дужки → (2) степені/корені → (3) × та ÷ → (4) + та −. Порушиш порядок — відповідь хибна.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди дужки — обчислюй їх першими</b><br>Від внутрішніх до зовнішніх: ((2+3)×4)+1 → (5×4)+1 → 20+1=21.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайди степені та корені — обчислюй другими</b><br>2³=8, √9=3 — до множення і ділення!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Множення та ділення — зліва направо</b><br>12÷4×3 = 3×3 = 9 (НЕ 12÷12=1!).</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Додавання та віднімання — зліва направо</b><br>10−3+2 = 7+2 = 9 (НЕ 10−5=5!).</div></div><div class=\"final-note\">⚠️ 2+3×4=14 (НЕ 20!). (2+3)×4=20. 2³+6÷2=8+3=11. Запам'ятай: «Дужки, Степені, Множення/Ділення, Додавання/Віднімання» — ДСМД.</div>"],[39,"Використання лінійки та транспортира","<div class=\"rule-note\">📐 <b>Лінійка та транспортир — точні інструменти.</b> Похибка при вимірюванні залежить від техніки, а не від очей.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Лінійка: постав 0 на початок відрізка</b><br>НЕ край лінійки, а позначку 0! Читай значення на другому кінці.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Транспортир: суміщуй центр із вершиною кута</b><br>Лінія 0°–180° — з однією стороною кута.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Читай значення там, де проходить друга сторона кута</b><br>Якщо кут гострий (<90°) — внутрішня шкала. Тупий (>90°) — зовнішня.</div></div><div class=\"final-note\">📏 Перевіряй себе: гострий кут <90°, прямий =90°, тупий >90°. Якщо намалював 130° а задача про гострий — помилка ще при побудові!</div>"],[40,"Пошук закономірностей у числових рядах","<div class=\"rule-note\">🔍 <b>Числовий ряд має правило (крок):</b> арифметична прогресія (однакова різниця) або геометрична (однакове відношення).</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди різниці між сусідніми числами</b><br>a₂−a₁, a₃−a₂, a₄−a₃…</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Якщо різниці однакові → арифметична прогресія</b><br>Крок d = різниця. Наступне число = попереднє + d.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Якщо різниці різні — знайди відношення</b><br>a₂÷a₁, a₃÷a₂… Якщо однакові → геометрична прогресія.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Геометрична: наступне = попереднє × q</b><br>де q — знайдене відношення.</div></div><div class=\"final-note\">📌 2, 5, 8, 11, … → різниця +3 → наступне: 14. 3, 6, 12, 24, … → відношення ×2 → наступне: 48. 1, 4, 9, 16, … → квадрати: 25!</div>"],[41,"Задачі на роботу та продуктивність","<div class=\"rule-note\">⚙️ <b>Продуктивність = Обсяг ÷ Час.</b> При спільній роботі — складай продуктивності (не часи!).</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди продуктивність кожного</b><br>p = 1 ÷ t (за час t він виконує 1 роботу). Перший за 4 год: p₁=1/4.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>При спільній роботі: p_заг = p₁ + p₂</b><br>Дробові продуктивності додаються, як звичайні дроби.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знайди спільний час: t_заг = 1 ÷ p_заг</b><br>Одна одиниця роботи ÷ сумарна продуктивність.</div></div><div class=\"final-note\">🔧 Перший косить за 4 год (p₁=1/4), другий за 6 год (p₂=1/6). p=1/4+1/6=3/12+2/12=5/12. t=12/5=2.4 год = 2 год 24 хв.</div>"],[42,"Як працювати з негативними числами","<div class=\"rule-note\">❄️ <b>Від'ємне число — це борг або рух ліворуч.</b> Два мінуси = плюс. Правило знаків знімає плутанину.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Уяви числову пряму</b><br>Права — плюс (+), ліва — мінус (−). Рух праворуч = додаємо, ліворуч = віднімаємо.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Додавання від'ємного = віднімання</b><br>5+(−3) = 5−3 = 2. 5−(−3) = 5+3 = 8 (мінус мінуса = плюс).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Правило знаків при множенні</b><br>(+)×(+)=+ | (−)×(+)=− | (−)×(−)=+. «Мінус на мінус дає плюс»!</div></div><div class=\"final-note\">📌 (−3)×(−4)=+12. (−3)+(−4)=−7 (обидва борги = більший борг). −10−(−3)=−10+3=−7. Борг 10 грн, пробачили 3 грн → борг 7 грн.</div>"],[43,"Логічні задачі на співвідношення","<div class=\"rule-note\">🧩 <b>Таблиця відповідностей</b> — найкращий метод для задач типу «хто де сидить / хто що робить». Виключай неможливе.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Склади таблицю: рядки — об'єкти, стовпці — ознаки</b><br>Усі можливі комбінації — на перетині.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Заповнюй знаками ✓ (так) і ✗ (ні)</b><br>На основі кожного факту з умови.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Правило: в кожному рядку і стовпці — рівно одна ✓</b><br>Знайшов ✓ → решта в рядку/стовпці = ✗.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Знаходь суперечності та виводь нові факти</b><br>Якщо в рядку залишилась одна порожня клітинка — ставь ✓.</div></div><div class=\"final-note\">🔎 «Аня, Боб, Сашко — лікар, вчитель, кухар. Аня — не лікар. Боб — не вчитель. Сашко — не кухар.» → Таблиця: Сашко=вчитель, Боб=лікар, Аня=кухар.</div>"],[44,"Одиниця вимірювання та їх переведення","<div class=\"rule-note\">📏 <b>Система SI:</b> кожна одиниця має префікс-множник. Переводити — значить множити або ділити на степінь 10.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запам'ятай ключові префікси</b><br>кіло (к) = ×1000. санти (с) = ÷100. мілі (м) = ÷1000.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Більша одиниця → менша: множи</b><br>2.5 км → м: 2.5×1000=2500 м. 3 кг → г: 3×1000=3000 г.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Менша одиниця → більша: ділення</b><br>300 г → кг: 300÷1000=0.3 кг. 450 см → м: 450÷100=4.5 м.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Час і площа — окремо</b><br>1 год=60 хв=3600 с. 1 м²=10000 см². 1 км²=1000000 м².</div></div><div class=\"final-note\">✅ 45 хв → год: 45÷60=0.75 год. 1.5 год → хв: 1.5×60=90 хв. Пам'ятай: «велике→мале = множ; мале→велике = ділення»!</div>"],[45,"Задачі на пропорції","<div class=\"rule-note\">⚖️ <b>Пропорція: a/b = c/d → a×d = b×c</b> (добутки «крест-навхрест» рівні). Знаєш три — знайдеш четверте.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запиши пропорцію: a:b = c:x</b><br>Або у вигляді дробів: a/b = c/x.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Застосуй правило крест-навхрест</b><br>a×x = b×c → x = b×c ÷ a.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевір</b><br>Обидва відношення мають бути рівні: a/b = c/x.</div></div><div class=\"final-note\">📌 «3 кг = 90 грн. 5 кг — скільки?» → 3/90=5/x → x=90×5÷3=150 грн. Пряма пропорція: більше кг → більше грошей. Обернена: більше швидкість → менше час.</div>"],[46,"Як правильно записувати умову задачи (Дано)","<div class=\"rule-note\">📝 <b>Стандарт оформлення:</b> Дано — Знайти — Розв'язок — Відповідь. Структура допомагає не загубити дані й не заплутатись.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Дано: виписуй кожну величину з позначенням</b><br>v=60 км/год, t=3 год. Коротко, без зайвих слів.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайти: чітко сформулюй що шукаєш</b><br>S=? або знайди відстань. Одна мета на задачу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Розв'язок: формула → підстановка → обчислення</b><br>S=v·t=60·3=180 км. Кожен крок — окремий рядок.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Відповідь: повне речення</b><br>Відстань становить 180 км. НЕ просто «180».</div></div><div class=\"final-note\">📋 Велосипедист 2 год по 15 км/год → Дано: v=15, t=2. Знайти: S. Розв'язок: S=15×2=30. Відповідь: Велосипедист проїхав 30 км.</div>"],[47,"Обчислення периметра та площі базових фігур","<div class=\"rule-note\">📐 <b>Периметр</b> — сума сторін (довжина огорожі). <b>Площа</b> — розмір поверхні. Формули треба знати напам'ять.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Квадрат і прямокутник</b><br>Квадрат: P=4a, S=a². Прямокутник: P=2(a+b), S=a×b.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Трикутник</b><br>P=a+b+c (сума трьох сторін). S=½×a×h (де h — висота на сторону a).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коло і круг</b><br>Довжина кола: L=2πr. Площа круга: S=πr² (π≈3.14).</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Складені фігури</b><br>Розбивай на прості → обчислюй кожну → складай.</div></div><div class=\"final-note\">🏠 Кімната 4м×5м: P=2(4+5)=18 м (плінтус), S=20 м² (підлога). Трикутник 6см, h=4см: S=½×6×4=12 см².</div>"],[48,"Як розкласти число на прості множники","<div class=\"rule-note\">🔢 <b>Просте число</b> — ділиться лише на 1 і на себе. Розкласти на прості множники = знайти «цеглинки» числа.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ділі на найменший простий множник</b><br>Починай з 2 (якщо парне). Потім 3 (якщо ділиться). Потім 5, 7…</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Результат знову ділити на прості множники</b><br>Продовжуй доки не залишиться просте число.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запиши розкладання у вигляді добутку</b><br>Збери всі множники з′єднані знаком ×.</div></div><div class=\"final-note\">📌 60: 60÷2=30 → 30÷2=15 → 15÷3=5 → 5 просте. 60=2²×3×5. НСД(12,18): 12=2²×3, 18=2×3² → НСД=2×3=6. НСК=2²×3²=36.</div>"],[49,"Порівняння чисел та виразів","<div class=\"rule-note\">⚖️ <b>Порівняння чисел:</b> однакові знаки → порівнюй величину; різні знаки → від'ємне завжди менше за додатне.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Натуральні числа</b><br>Більше цифр → більше. Однакова кількість → порівнюй зліва направо, розряд за розрядом.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Дроби з рівними знаменниками</b><br>Більший чисельник → більший дріб. 5/8 > 3/8.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Дроби з різними знаменниками</b><br>Зведи до спільного знаменника → порівняй чисельники.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Від'ємні числа</b><br>На числовій прямій: лівіше = менше. −5 < −1 (хоча 5 > 1).</div></div><div class=\"final-note\">📌 3/4 чи 5/7? → 21/28 чи 20/28 → 21/28>20/28 → 3/4>5/7. Порівняй вирази: 2×(3+4) чи 5×3? → 14 чи 15 → 14<15.</div>"],[50,"Самостійне складання задач","<div class=\"rule-note\">🌟 <b>Скласти задачу</b> — значить придумати реальну ситуацію під математичну модель. Це найглибше розуміння теми.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Вибери формулу або операцію</b><br>Наприклад: S=v×t, або площа прямокутника, або задача на %.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Придумай реальну ситуацію</b><br>Велосипед, магазин, будівництво, кухня — що завгодно!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Задай конкретні числа і сформулюй запитання</b><br>Числа мають давати «красиву» відповідь (ціле число).</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перевір: чи розв'язується? Чи відповідь реальна?</b><br>Якщо відповідь — 0.00013 людини, щось не так.</div></div><div class=\"final-note\">💡 S=a×b → «Город 8м×5м. Яка площа?» → 40 м². Обернена: «Площа 40 м², ширина 5 м. Знайди довжину.» Склавши задачу — розумієш її повністю!</div>"],[51,"Як уникати арифметичних помилок від неуважності","<div class=\"rule-note\">🎯 <b>80% арифметичних помилок — помилки УВАГИ,</b> а не незнання. Три прийоми їх усувають.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Пиши акуратно — стовпчиком, з рівними знаками</b><br>Нерозбірливий запис = хибне читання. Одна дія — один рядок.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перевіряй оберненою дією</b><br>Множення → ділення. Додавання → віднімання. Завжди!</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Оцінюй відповідь логічно</b><br>«Чи реальна ця відповідь?» 2 яблука × 3 = 60 — явна помилка!</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перечитуй умову після отримання відповіді</b><br>Чи те знайшов? Чи правильні одиниці виміру?</div></div><div class=\"final-note\">⏱️ На контрольній: залиш 5 хвилин на перевірку. Не здавай без перегляду — це не «витрата часу», це + 1–2 бали. Одна знайдена помилка варта більше ніж поспіх.</div>"]]},{"n":"✍️ Письмо, творчість та домашні завдання","e":"","cards":[[52,"Структура шкільного твору","<div class=\"rule-note\">📄 <b>Шкільний твір = 3 обов'язкові частини:</b> Вступ (тема + теза) → Основна частина (докази) → Висновок (підсумок). Порушиш структуру — знизять оцінку.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Вступ (10–15% обсягу)</b><br>Введи читача в тему. Сформулюй тезу — головну думку, яку доводитимеш.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Основна частина (70–75% обсягу)</b><br>2–3 абзаци-докази. Кожен: твердження → приклад → мікровисновок.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Висновок (15% обсягу)</b><br>Підсумуй докази. Підтверди тезу. Не повторюй вступ дослівно.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Оформлення</b><br>Новий абзац — відступ 1–1.5 см. Між частинами — логічний перехід.</div></div><div class=\"final-note\">📌 Обсяг: початкова школа ~100–150 слів, середня ~200–300. Перед написанням — чернетка плану: Теза → Доказ 1 → Доказ 2 → Висновок.</div>"],[53,"Як сформулювати тезу для твору","<div class=\"rule-note\">🎯 <b>Теза</b> — одне речення, що відповідає на запитання теми і є центральною думкою твору. Слабка теза = слабкий твір.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай тему і перефразуй її у запитання</b><br>«Дружба — велика цінність» → «Чому дружба важлива?»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Дай конкретну відповідь — це і є теза</b><br>НЕ «Я думаю, що дружба важлива» → «Справжня дружба дає опору в найскладніші моменти.»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевір тезу за трьома критеріями</b><br>(1) Одна думка? (2) Можна довести прикладами? (3) Це не факт, а твердження?</div></div><div class=\"final-note\">✅ Слабка: «У творі я розкажу про дружбу.» Сильна: «Справжній друг пізнається не в радості, а у скруті.» Тезу пиши першою — вона керує всім твором.</div>"],[54,"Підбір доказів та прикладів","<div class=\"rule-note\">🔍 <b>Доказ = твердження + приклад + пояснення.</b> Три джерела прикладів: власний досвід, прочитані книги, відомі факти.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Сформулюй твердження до тези</b><br>По-перше, дружба проявляється у взаємодопомозі.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Наведи конкретний приклад</b><br>Наприклад, герой роману «Том Сойєр» Гек Фін рятує друга ціною власної безпеки.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Поясни зв'язок з тезою</b><br>Це підтверджує: справжній друг діє, а не лише говорить.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Уникай розмитих прикладів</b><br>НЕ «багато людей так роблять» — конкретна особа/подія/книга.</div></div><div class=\"final-note\">📌 Три типи прикладів: (1) «Я бачив/зробив…» — особистий. (2) «У книзі X герой Y…» — літературний. (3) «Вчені довели / відомо що…» — фактичний.</div>"],[55,"Робота з синонімами","<div class=\"rule-note\">📚 <b>Синоніми</b> — слова з близьким значенням. Замінюй повтори синонімами — текст стане багатшим і грамотнішим.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди слово, яке повторюється</b><br>Підкресли або виділи всі повтори одного слова в тексті.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Добери 2–3 синоніми</b><br>Словник синонімів або власний запас. Наприклад: сказав → промовив, відповів, зазначив, підкреслив.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевір значення перед заміною</b><br>Синоніми не завжди взаємозамінні: «великий» ≠ «величезний» у всіх контекстах.</div></div><div class=\"final-note\">💡 Слово «йти»: крокувати, прямувати, рухатись, мчати, бігти — кожне передає різну швидкість і настрій. Веди власний «Словничок синонімів» у зошиті.</div>"],[56,"Метод швидкого початку письма","<div class=\"rule-note\">⚡ <b>Синектика старту:</b> не чекай натхнення — почни писати будь-що. Перші 3 хвилини — найважчі. Є три способи розпочати.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Почни з риторичного запитання</b><br>«Чи замислювались ви, що означає бути справжнім другом?»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Почни з яскравої деталі або сцени</b><br>«Тієї осені я зрозумів, що деякі люди входять у наше життя назавжди.»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Почни з афоризму або цитати</b><br>«Скажи мені, хто твій друг, і я скажу, хто ти» — так стверджує стародавня мудрість.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Якщо нічого не виходить — пиши план</b><br>Запиши 5 ключових слів теми. Розгорни кожне у речення. Це і є чернетка.</div></div><div class=\"final-note\">⏱️ Правило 2 хвилин: як тільки отримав тему — одразу пиши перше речення, будь-яке. Перфекціонізм вбиває твір ще до першого слова.</div>"],[57,"Як писати диктанти без паніки","<div class=\"rule-note\">🎧 <b>Диктант — не покарання, а тренування уваги.</b> Три чверті помилок — від поспіху та неуважності, а не від незнання правил.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Слухай фразами, не словами</b><br>Утримуй у пам'яті все речення — тоді зрозумієш логіку та пунктуацію.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пиши і думай одночасно</b><br>Під час написання — правило в голові: «и чи і?», «велика чи мала?»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перший перегляд — орфографія</b><br>Прочитай написане, перевіряючи кожне слово окремо.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Другий перегляд — пунктуація</b><br>Перевір кожну кому та крапку: чи є основа речення з кожного боку?</div></div><div class=\"final-note\">📝 Якщо сумніваєшся у слові — напиши розбірливіше, щоб можна було виправити. Чисте виправлення краще, ніж хибне слово. Залиш 3–5 хвилин на перевірку.</div>"],[58,"Оформлення шкільних зошитів","<div class=\"rule-note\">📓 <b>Акуратний зошит = +1–2 бали</b> автоматично. Охайність — це повага до вчителя і до власної праці.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Дата і назва роботи — обов'язково</b><br>Дата — на рядку з лівого краю. «Класна робота» / «Домашня робота» — посередині.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Відступи між роботами</b><br>Між домашньою і класною — 2 рядки (клітинки). Між вправами — 1 рядок.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Поля — не порушувати</b><br>Не заходь за червону лінію поля. Там — помітки вчителя.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Виправлення — акуратно</b><br>Одна риска — не замальовувати. Якщо треба переписати — нова сторінка.</div></div><div class=\"final-note\">✏️ Перевірка за 10 секунд: (1) підписаний зошит? (2) є дата? (3) є назва роботи? (4) вкладений у щоденник? Так → зошит готовий до здачі.</div>"],[59,"Складання розповіді за малюнком","<div class=\"rule-note\">🖼️ <b>Малюнок = готовий план розповіді.</b> Дивись не на картинку, а в неї — шукай хто, де, коли, що, навіщо.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розглянь малюнок і дай відповідь на 5 питань</b><br>Хто зображений? Де відбувається? Коли (пора року/доба)? Що роблять? Який настрій?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Склади план: початок → подія → кінець</b><br>Початок: де і хто. Подія: що відбулося. Кінець: чим завершилось або що відчувають.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Розгорни кожну частину у 2–3 речення</b><br>Описуй деталі: колір, рух, звук — щоб розповідь «ожила».</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перевір: чи є початок і кінець?</b><br>Розповідь без кінця — незавершена думка.</div></div><div class=\"final-note\">📌 Корисні слова: «На малюнку зображено…», «Схоже, що…», «Мені здається, герой відчуває…» — ці фрази допомагають почати й не мовчати.</div>"],[60,"Правильне ведення щоденника","<div class=\"rule-note\">📔 <b>Щоденник</b> — не звіт про день, а розмова з собою. Три хвилини щовечора — і думки впорядковані.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запис = дата + 3 елементи</b><br>(1) Що трапилось важливого. (2) Що відчував. (3) Що хочу зробити інакше.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пиши без редагування</b><br>Щоденник — не твір на оцінку. Пиши як думаєш, навіть з помилками.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перечитуй раз на місяць</b><br>Помічай: що змінилось, що повторюється, що вирішено.</div></div><div class=\"final-note\">💡 Лайфхак: перші два тижні пиши хоча б 3 речення. Дослідження звичок (Lally et al., 2010) показують: звичка зазвичай формується за 2 місяці і більше — але постійність важливіша за швидкість. Щоденник розвиває мовлення і допомагає зрозуміти себе.</div>"],[61,"Як готувати домашнє завдання з мови","<div class=\"rule-note\">📖 <b>Домашнє з мови — це не «переписати» а «зрозуміти правило і застосувати».</b> Алгоритм у 4 кроки.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай правило</b><br>Не параграф цілком — знайди правило для конкретного завдання. Прочитай 2 рази.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розбери приклади з підручника</b><br>Чому саме так? Яке слово є винятком? Запиши у зошит своїм прикладом.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Виконай вправу — перевіряй кожне слово</b><br>Не все підряд, а слово за словом: «Яке тут правило? Я пам'ятаю?»</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перевір за ключем або сам</b><br>Прочитай вголос — помилки чуються краще.</div></div><div class=\"final-note\">⏱️ Час: не більше 20–25 хвилин на мову. Якщо не виходить — відкрий правило і спробуй знову. Більше 30 хвилин — питай у вчителя.</div>"],[62,"Робота над помилками (Аналіз)","<div class=\"rule-note\">🔄 <b>Робота над помилками</b> — найефективніший метод навчання. Не переписуй правильно — ЗРОЗУМІЙ, чому помилився.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знайди помилку і визнач тип</b><br>Орфографічна (правопис)? Пунктуаційна (розділові знаки)? Граматична (форма слова)?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайди відповідне правило</b><br>Відкрий підручник, знайди правило. Запиши номер параграфа.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запиши слово/речення правильно 3 рази</b><br>Три рази — рука запам'ятовує краще ніж голова.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Склади 1–2 власних приклади</b><br>Придумай своє речення з тим самим правилом. Це — закріплення.</div></div><div class=\"final-note\">📌 Метод: виправлена помилка → правило → 3 рази → власний приклад. Якщо ту саму помилку зробив двічі — правило не засвоєне: повтори параграф повністю.</div>"],[63,"Як навчитися писати каліграфічно","<div class=\"rule-note\">✍️ <b>Каліграфія</b> — не природжений талант, а навичка. Мозок і рука навчаються через повторення і правильну позу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правильна поза і тримання ручки</b><br>Спина пряма. Зошит під кутом 30°. Ручка лежить на середньому пальці, тримають великий і вказівний.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Тренуй елементи окремо</b><br>Пишеш «і» — відпрацюй вертикальний штрих. Пишеш «о» — відпрацюй овал. Не поспішай.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Пиши повільніше за звичай</b><br>Швидкість — ворог каліграфії. Свідомо уповільнись: контролюй кожен штрих, тиск і нахил.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Порівнюй з еталоном</b><br>Зразок прописів поряд — порівнюй кожну букву. Знайди 3 відмінності — виправ.</div></div><div class=\"final-note\">⏱️ 5 хвилин каліграфічного тренування щодня — за місяць почерк зміниться. Корисна вправа: пиши великі букви у повільному темпі, стежачи за натиском.</div>"],[64,"Складання сенкану (п'ятирядка)","<div class=\"rule-note\">🌟 <b>Сенкан (cinq — п'ять)</b> — 5-рядкова нерифмована поезія за чіткою схемою. Розвиває образне мислення і словниковий запас.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Рядок 1 — іменник (тема)</b><br>Одне слово. Наприклад: Осінь.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Рядок 2 — два прикметники</b><br>Яка? Яскрава, сумна.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Рядок 3 — три дієслова</b><br>Що робить? Шелестить, жовтіє, прощається.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Рядок 4 — фраза (4 слова)</b><br>Думка про тему: «Час прощання і відпочинку.» Рядок 5 — синонім або підсумок (1 слово): Листопад.</div></div><div class=\"final-note\">📌 Осінь. / Яскрава, сумна. / Шелестить, жовтіє, прощається. / Час прощання і відпочинку. / Листопад. — Сенкан готовий! Використовується на уроках для підсумку теми.</div>"],[65,"Підготовка до переказу","<div class=\"rule-note\">🔄 <b>Переказ</b> — не заучування тексту напам'ять, а передача суті своїми словами. Структура та ключові слова — твої опори.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай текст 2 рази і визнач тему</b><br>Перший раз — загальне розуміння. Другий — деталі.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Склади план: 3–5 ключових пунктів</b><br>Кожен пункт — одна думка. Пиши короткими фразами.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знайди ключові слова кожної частини</b><br>5–7 слів на абзац, які не можна замінити — їх запам'ятай.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перекажи вголос за планом</b><br>Спочатку з планом перед очима, потім — без. Запиши і послухай.</div></div><div class=\"final-note\">📝 Правило «своїх слів»: синоніми дозволені, факти і цифри — точно. Якщо забув деталь — перефразуй загально: «герой зробив важливий вибір» замість конкретної дії.</div>"],[66,"Як вести читацький щоденник","<div class=\"rule-note\">📗 <b>Читацький щоденник</b> — коротка картка кожної прочитаної книги. За рік накопичується база, яка рятує на контрольних.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запис = 6 обов'язкових полів</b><br>Автор. Назва. Рік. Жанр. Головні герої. Коротко сюжет (3–5 речень).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Додай особисту оцінку</b><br>Що сподобалось? Що не сподобалось? Оцінка 1–10 і 1 речення «чому».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запиши цитату або думку</b><br>Одна фраза, яка вразила. Або: «Головна думка: …»</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перечитуй перед контрольною</b><br>За 10 хвилин пробіжишся по 10–15 книгах — і все пригадаєш.</div></div><div class=\"final-note\">💡 Мінімальний формат: «Автор. Назва. Герої: X, Y. Сюжет: … Думка: …» — навіть 5 рядків краще, ніж нічого. Почни вже з наступної книги!</div>"],[67,"Написання листів та листівок","<div class=\"rule-note\">✉️ <b>Лист має структуру:</b> Звернення → Вступ → Основна частина → Завершення → Підпис. Порушиш — лист виглядає невиховано.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Звернення: Дорогий/Шановний + ім'я + !</b><br>Дорогий Максиме! / Шановна Оленко Петрівно!</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Вступ: як справи, привітання</b><br>«Щиро вітаю тебе з Новим роком! Сподіваюся, у тебе все добре.»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Основна частина: суть листа</b><br>Розкажи що хотів, запитай що цікавить. Абзац на кожну думку.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Завершення і підпис</b><br>«З повагою, …» / «Твій друг, …» / «До побачення, …» — відповідно до стилю.</div></div><div class=\"final-note\">📌 Листівка — коротший формат: Привітання → Побажання (2–3 речення) → Підпис. Для листівки достатньо 5–6 речень. Вчи на реальному прикладі — напиши комусь листа!</div>"],[68,"Техніка створення стінгазети чи плаката","<div class=\"rule-note\">🗞️ <b>Стінгазета = текст + зображення + композиція.</b> Три правила: читається за 30 секунд, одна головна думка, очевидна структура.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач тему і головну думку</b><br>Одне речення: «Ця стінгазета про…» Решта — деталі навколо цієї думки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розбий на блоки</b><br>Заголовок (великий, по центру). 2–4 блоки тексту. Малюнки або фото. Рамки або лінії для порядку.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Правило читабельності</b><br>Великий шрифт заголовка. Короткі абзаци (3–5 речень). Між блоками — відстань.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Колір і акцент</b><br>Не більше 3 кольорів. Найважливіше — виділи жирним або рамкою.</div></div><div class=\"final-note\">✅ Перевірка: відійди на 2 метри. Чи видно заголовок? Чи зрозуміло про що? Чи не заплутано? Якщо так — готово!</div>"],[69,"Як готувати доповідь на 3 хвилини","<div class=\"rule-note\">🎤 <b>3 хвилини = ~300–350 слів.</b> Не читай з аркуша — розповідай. Структура: зачіпка → суть → висновок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Зачіпка (15 сек): запитання або факт</b><br>«Чи знаєте ви, що…?» або «Уявіть, що…» — привертає увагу одразу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Суть (2 хв): 2–3 ключових факти</b><br>Не переказуй все — вибери найважливіше. Кожен факт — 1 абзац.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Висновок (30 сек)</b><br>Одне речення: «Отже, … тому що …» і заклик або запитання до аудиторії.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Репетиція з таймером</b><br>Скажи вголос — виміряй час. 3 хвилини = звичний темп мовлення.</div></div><div class=\"final-note\">💡 Шпаргалка: 3–5 ключових слів на картці, НЕ повний текст. Контакт з аудиторією — дивись на людей, а не в папір. Голос — гучніше на 20% від звичного.</div>"],[70,"Використання словників (орфографічний, тлумачний)","<div class=\"rule-note\">📖 <b>Словник</b> — не «ліниво, бо не знаю», а «розумно, бо перевіряю». Три основних словники для школяра.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Орфографічний словник</b><br>Для перевірки правопису. Слова за алфавітом. Корисно: виняткові слова, слова іншомовного походження.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Тлумачний словник</b><br>Пояснює значення слів. Шукай, коли не розумієш слово або хочеш точніше сформулювати.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Словник синонімів</b><br>Замінюй повтори. Шукай за ключовим словом — отримуєш 5–10 варіантів.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Як швидко знайти слово</b><br>Алфавіт → перша буква → друга буква → третя. Вкладки або помітки на полях прискорюють пошук.</div></div><div class=\"final-note\">📌 Лайфхак: для підручникового орфографічного онлайн — sum.in.ua або r2u.org.ua. Для тлумачного — slovnyk.ua. Перевіряй сумнівне слово одразу, не відкладай.</div>"],[71,"Складання опису предмета чи тварини","<div class=\"rule-note\">🔎 <b>Опис</b> — це портрет словами. Головне правило: від загального до конкретного, від зовнішнього до деталей.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Вступне речення: що описуєш і загальне враження</b><br>«Перед нами — маленький пухнастий кошеня з хитрими очима.»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Зовнішній вигляд: форма, розмір, колір</b><br>Опиши послідовно: голова → тулуб → лапи/хвіст. Або: верх → низ.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Деталі: характерні особливості</b><br>Те, що робить предмет/тварину унікальним: пляма на вусі, зігнутий ріг.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Завершення: враження або дія</b><br>«Це кошеня завжди стрибає на підвіконня і слідкує за горобцями.»</div></div><div class=\"final-note\">📌 Для тварини додай: як рухається, який звук видає, де живе, що їсть. Використовуй порівняння: «очі як смарагди», «хутро м'яке мов пух».</div>"],[72,"Як писати роздум на вільну тему","<div class=\"rule-note\">💭 <b>Роздум</b> — найскладніший жанр: потрібно не розповісти, а ДОВЕСТИ думку. Структура: теза → аргументи → висновок.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Сформулюй тезу — чітку позицію</b><br>НЕ «Я хочу розповісти про сміливість» а «Сміливість — це не відсутність страху, а дія всупереч страху.»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Наведи 2 аргументи з прикладами</b><br>По-перше… (приклад). По-друге… (приклад). Аргументи мають бути різними за типом.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Допусти контраргумент і спростуй</b><br>«Дехто може заперечити, що… Однак…» — це ознака зрілого мислення.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Висновок: підтверди тезу</b><br>Не повторюй дослівно — переформулюй. «Отже, справжня сміливість полягає у…»</div></div><div class=\"final-note\">📌 Вільна тема — найважча: без рамок легше загубитись. Порада: вибери найпростішу тезу, яку можеш довести двома сильними прикладами.</div>"],[73,"Редагування власних робіт","<div class=\"rule-note\">✏️ <b>Редагування</b> — це не пошук помилок, а покращення тексту. Три кола читання: зміст → мова → правопис.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Перше коло: зміст і логіка</b><br>Чи розкрита тема? Чи є теза і висновок? Чи всі абзаци пов'язані?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Друге коло: мова і стиль</b><br>Прибери повтори (синоніми!). Скороти довгі речення. Знайди розмовні слова і заміни книжними.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Третє коло: правопис і пунктуація</b><br>Кожне слово окремо. Кожна кома — чи потрібна? Великі літери, відступи.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Читай вголос</b><br>Вухо чує те, що очі пропускають. Там де запнувся — виправ.</div></div><div class=\"final-note\">⏱️ Дай тексту «відпочити» 10–15 хвилин, потім читай. Свіжий погляд знаходить удвічі більше. Гарна робота = написання + редагування.</div>"],[74,"Створення інтерактивних буклетів","<div class=\"rule-note\">📋 <b>Буклет = компактний носій інформації:</b> аркуш А4, зігнутий втричі. Три панелі — три логічні блоки.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розплануй три панелі</b><br>Права (обкладинка): назва + зображення. Центральна: головна інформація. Ліва (задня): контакти/підсумок.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Правило буклету: менше — краще</b><br>Коротко: заголовки, списки, цифри. Не суцільний текст — читач не читатиме.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Графіка і колір</b><br>Одна колірна схема (2–3 кольори). Малюнки або піктограми для кожного блоку.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перевір перед друком</b><br>Роздрукуй чернетку, зігни — чи правильно розташовані панелі? Чи читається після складання?</div></div><div class=\"final-note\">💡 Цифровий варіант: Canva (безкоштовно) → шаблон «буклет» → замінюй текст і зображення → готово за 20 хвилин. Роздрукуй і принеси на урок!</div>"],[75,"Як писати стислий переказ","<div class=\"rule-note\">✂️ <b>Стислий переказ</b> = 1/3 від обсягу оригіналу. Залиши суть, відкинь деталі. Не скорочуй кожне речення — відкидай цілі блоки.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прочитай і визнач головну думку кожного абзацу</b><br>Одне речення на абзац — це мікроплан.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Залиши тільки ключові події, факти, аргументи</b><br>Описи природи, діалоги, повтори — скорочуй або прибирай.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Поєднай скорочені думки плавно</b><br>Використовуй зв'язки: «Крім того», «Однак», «Таким чином», «Внаслідок цього».</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Перевір обсяг</b><br>Якщо оригінал 300 слів — твій переказ ~100 слів. Порахуй рядки.</div></div><div class=\"final-note\">📌 Часта помилка: переказ = список фактів без зв'язку. Виправлення: між реченнями — логічний зв'язок. «Герой зробив X. Тому Y сталося. Це призвело до Z.»</div>"],[76,"Підготовка до шкільного конкурсу творів","<div class=\"rule-note\">🏆 <b>Конкурсний твір ≠ шкільний твір.</b> Там оцінюють оригінальність, мову і структуру. Три тижні підготовки — реальний результат.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Тиждень 1: читання та ідеї</b><br>Прочитай 3–5 кращих зразків жанру. Запиши 5–7 ідей. Вибери найоригінальнішу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Тиждень 2: написання і редагування</b><br>Чернетка → перший варіант → редагування за трьома колами. Дай прочитати дорослому.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Тиждень 3: шліфування</b><br>Перевір: оригінальний початок? Сильний фінал? Немає банальностей? Немає помилок?</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Оформлення</b><br>Шрифт, поля, відступи — за вимогами конкурсу. Титульна сторінка.</div></div><div class=\"final-note\">🌟 Секрет переможця: пиши про те, що справді хвилює. Щирість і конкретика б'ють штамповані теми. Почни з незвичної деталі — суддя читає 50+ робіт і чекає на несподіванку.</div>"]]},{"n":"🎒 Шкільна самоорганізація, дисципліна та адаптація","e":"","cards":[[77,"Збирання портфеля з вечора","<div class=\"rule-note\">🎒 <b>Портфель з вечора</b> — ранок без паніки. Правило: зібрав увечері = не забув вранці. Займає 5 хвилин, рятує 20.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Відкрий розклад на завтра</b><br>Запиши або переглянь: які уроки, які потрібні підручники та зошити.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Склади підручники і зошити за розкладом</b><br>Знизу — важке (підручники), зверху — легке (зошити). Перевір кожен предмет.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевір приладдя</b><br>Ручки (2 шт.), олівець, лінійка, гумка, циркуль — якщо потрібен. Пенал повний?</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Поклади «незабувашки»</b><br>Щоденник. Змінне взуття. Гроші. Телефон на зарядку — поряд з портфелем.</div></div><div class=\"final-note\">✅ Контрольний список на стіні або в телефоні: 5 пунктів — 30 секунд перевірки. Якщо забував щось конкретне — додай окремим пунктом.</div>"],[78,"Правило «Чистий робочий стіл»","<div class=\"rule-note\">🗂️ <b>Чистий стіл = чиста голова.</b> Безлад навколо створює безлад у думках. П'ять хвилин прибирання до роботи — подвоюють фокус.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Прибери все зайве зі столу</b><br>Залиш лише те, що потрібно для конкретного завдання прямо зараз.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Три зони: \"Роблю зараз\", \"Потім\", \"Не тут\"</b><br>\"Роблю\" — перед тобою. \"Потім\" — у стосі праворуч. \"Не тут\" — прибрати зі столу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Після роботи — стіл чистий</b><br>Правило: не встаєш поки стіл не прибраний до стану \"до\". Займає 2 хвилини.</div></div><div class=\"final-note\">💡 Психологічний ефект: мозок сприймає безлад як незавершені задачі. Чистий стіл = сигнал «можна зосередитись». Спробуй тиждень — помітиш різницю.</div>"],[79,"Організація часу на домашнє завдання (Метод 25/5)","<div class=\"rule-note\">⏱️ <b>Метод Помодоро: 25 хвилин роботи + 5 хвилин відпочинку.</b> Мозок підліткa концентрується максимум 25–30 хвилин. Не борись — використай.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запиши список завдань до виконання</b><br>Перелік предметів і що саме зробити. Оціни: скільки «помідорів» потрібно?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Запусти таймер на 25 хвилин</b><br>Телефон — у режим «не турбувати». Соцмережі — закрити. Тільки завдання.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли дзвенить — 5 хвилин відпочинку</b><br>Встань, потягнися, виглянь у вікно. НЕ соцмережі — мозок не відпочиває.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Після 4 «помідорів» — великий відпочинок 15–20 хв</b><br>Поїж, погуляй, поговори. Потім — наступний блок.</div></div><div class=\"final-note\">📌 Для коротких завдань (до 10 хв): не запускай таймер — просто зроби. Метод для середніх і великих задач. Застосунок: Forest, Be Focused або звичайний таймер телефону.</div>"],[80,"Чергування предметів","<div class=\"rule-note\">🔄 <b>Чергування = профілактика втоми мозку.</b> Не роби 3 години математику підряд — чергуй «важке» з «легким» і «точне» з «творчим».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розділи предмети на типи</b><br>Точні (математика, фізика). Гуманітарні (мова, історія). Творчі (малювання, музика, твір).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Чергуй типи</b><br>Математика → Мова → Математика → Малювання. НЕ: Математика → Фізика → Хімія.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Складне — на початку, легке — наприкінці</b><br>Коли сил більше — важкі предмети. Коли втомився — повторення або легкі завдання.</div></div><div class=\"final-note\">💡 Правило: після точного — гуманітарне, після гуманітарного — рух або відпочинок. Мозок «переключається» і відновлюється навіть під час навчання.</div>"],[81,"Як правильно підготувати одяг до школи","<div class=\"rule-note\">👔 <b>Одяг з вечора</b> — ще один ранок без поспіху. 3 хвилини ввечері = 10 хвилин зекономлених вранці.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Звечора вибери повний комплект</b><br>Усе: футболка, штани/спідниця, шкарпетки, білизна. Повісь або склади в одне місце.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перевір чистоту</b><br>Немає плям? Не пом'ято критично? Якщо треба прасувати — зроби ввечері, не вранці.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Взуття — поряд з виходом</b><br>Чисте, зі шнурками. Змінне взуття — в портфелі або окремо.</div></div><div class=\"final-note\">📌 Лайфхак: заведи «шкільну» поличку або гачок — туди вішаєш тільки шкільне. Ніколи не перемішується з домашнім одягом. Ранок стає автоматичним.</div>"],[82,"Поведінка на уроці","<div class=\"rule-note\">🏫 <b>Поведінка на уроці</b> — це не лише вихованість, а стратегія навчання. Активна участь = краще розуміння + вища оцінка.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Сідай і готуй матеріали до дзвінка</b><br>Підручник, зошит, ручка — на столі. Не метушись після початку уроку.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Слухай активно: записуй ключове</b><br>Не переписуй все — записуй заголовки, цифри, незрозумілі слова. Питання — на полях.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Піднімай руку — навіть якщо не впевнений</b><br>«Я думаю, що…» — це не помилка, це участь. Вчитель бачить тих, хто намагається.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Не відволікайся і не відволікай інших</b><br>Телефон — у портфелі. Розмови — після дзвінка. Повага до класу = повага до себе.</div></div><div class=\"final-note\">💡 Правило 2 запитань: за урок постав хоча б 2 запитання або дай 2 відповіді. Активні учні краще засвоюють матеріал і рідше «губляться» перед контрольними.</div>"],[83,"Як вчасно прокинутися вранці","<div class=\"rule-note\">⏰ <b>Прокидатися вчасно</b> — це не про силу волі, а про систему. Три звички змінюють ранок назавжди.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Лягай і вставай в один і той самий час</b><br>Навіть у вихідні ±30 хв. Біоритми налаштовуються за 2–3 тижні — прокидатися стає легше.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Поклади телефон (будильник) далеко від ліжка</b><br>Щоб вимкнути — треба встати. Встав → вийшов з кімнати → прокинувся.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перший крок після будильника</b><br>Одразу: умийся холодною водою. Тіло «вмикається» за 90 секунд.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Вечірня підготовка = легкий ранок</b><br>Портфель зібрано. Одяг обрано. Сніданок простий. Мозок не витрачає сили на рішення.</div></div><div class=\"final-note\">📌 Оптимальний сон для школяра: 8–9 годин. Лягти о 22:00 — прокинутися о 6:30 без проблем. Недосип = знижена увага, гірша пам'ять, гірші оцінки.</div>"],[84,"Організація шкільного приладдя","<div class=\"rule-note\">✏️ <b>Організоване приладдя</b> — знаходиш за 3 секунди, не витрачаєш час на пошуки. Одне місце для всього.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Пенал: мінімальний обов'язковий набір</b><br>2 ручки (синя + запасна), олівець, гумка, лінійка 20 см. Всі — робочі, перевірені.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Система зошитів</b><br>Підпис: предмет + клас + прізвище. Окремий зошит для кожного предмету. Не мішай предмети в одному зошиті.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Щоденник — основний інструмент</b><br>Записуй домашнє завдання одразу на уроці, не «потім». Дата, предмет, конкретне завдання.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Ревізія раз на місяць</b><br>Викинь непотрібне, допишіть ручки, замін зламане. Портфель не повинен важити більше 3–4 кг.</div></div><div class=\"final-note\">💡 Кольорова система: різний колір обкладинки зошита для кожного предмету. Математика — синій, мова — зелений, історія — жовтий. Знаходиш миттєво.</div>"],[85,"Як поводитися під час конфлікту в класі","<div class=\"rule-note\">🤝 <b>Конфлікт — це не катастрофа, а навичка.</b> Той, хто вміє вирішувати конфлікти спокійно — виграє завжди.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Зупинись і не реагуй одразу</b><br>«Пауза 5 секунд»: глибокий вдих, рахуй до 5. Гострі слова, сказані одразу — шкодять тобі.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Скажи про свої відчуття, не звинувачуй</b><br>НЕ «Ти завжди…» → «Мені неприємно, коли…» Це не слабкість — це сила.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запропонуй рішення, не продовжуй сварку</b><br>«Давай домовимось…» / «Як нам це вирішити?» Той, хто пропонує рішення — лідер ситуації.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Якщо не виходить — звернись до дорослого</b><br>Класний керівник, психолог, батьки. Просити допомогу — це розумно, не слабко.</div></div><div class=\"final-note\">📌 Заборонено: бити, ображати, мовчати і накопичувати. Дозволено: говорити, домовлятись, йти, просити допомоги. Конфлікт, вирішений вчасно, зміцнює стосунки.</div>"],[86,"Правило виконання складних завдань першими","<div class=\"rule-note\">🐸 <b>«Їж жабу вранці»</b> — найскладніше завдання виконуй першим. Поки сил і уваги найбільше. Решта пройде легше.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Визнач «жабу» дня</b><br>Яке завдання ти найбільше відкладаєш? Яке найважливіше? Це і є «жаба».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Починай з неї — без розгону</b><br>Не «спочатку перевірю телефон», не «спочатку легке». Відкрив зошит — почав «жабу».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Розбий на перший крок</b><br>Якщо «жаба» занадто велика: зроби ЛИШЕ перший крок (5 хвилин). Зазвичай цього достатньо, щоб почати.</div></div><div class=\"final-note\">💡 Психологія: відкладене складне завдання «висить» у голові та з'їдає енергію цілий день. Зробив — і голова вільна. Метод «жаби» + Помодоро = продуктивний день.</div>"],[87,"Як працювати в групі на уроці","<div class=\"rule-note\">👥 <b>Групова робота — це навичка XXI століття.</b> Уміння домовлятись і розподіляти завдання цінується більше, ніж «знати все самому».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Одразу розподіліть ролі</b><br>Лідер (координує), Секретар (записує), Доповідач (представляє), Контролер (перевіряє). Навіть у парі.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Слухай і не перебивай</b><br>Кожен говорить по черзі. Незгода — «Я думаю інакше, тому що…», а не «Ні, ти не правий!»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Слідкуй за часом</b><br>Лідер стежить за часом. За 2 хвилини до кінця — підбивайте підсумок.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Роби свою частину якісно</b><br>Якщо ти «схалтуриш» — підведеш усю групу. Репутація надійного партнера — цінна.</div></div><div class=\"final-note\">📌 Якщо хтось не працює — скажи спокійно: «Нам потрібна твоя частина, що ти зробиш?» Не скаржся — вирішуй. Це і є лідерство.</div>"],[88,"Правильне підготовка до контрольної роботи","<div class=\"rule-note\">📋 <b>Підготовка до контрольної = система, а не паніка.</b> Трьохденний план кращий за нічне зубріння.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>За 3 дні: огляд теми</b><br>Переглянь всі теми, що будуть. Знайди «білі плями» — чого не розумієш. Запиши питання.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>За 2 дні: опрацювання</b><br>Поясни матеріал собі вголос або другу. Розв'яжи 5–10 типових прикладів. Запам'ятай формули.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>За 1 день: повторення і відпочинок</b><br>Переглянь найскладніше. Більше 1,5 год не вчи. Лягай вчасно — мозок фіксує матеріал уві сні.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Ранок контрольної</b><br>Не читай нове. Переглянь шпаргалку (навіть якщо не дозволено — вона допомагає структурувати). Поїж.</div></div><div class=\"final-note\">📌 Ніч без сну перед контрольною — мінус 20–30% ефективності. Сон важливіший за останні 2 години зубріння. Це наукований факт, не відмовка.</div>"],[89,"Як ведення щоденника вражень","<div class=\"rule-note\">📓 <b>Щоденник вражень</b> — не журнал подій, а тренування емоційного інтелекту. 5 хвилин ввечері — і краще розумієш себе.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Три запитання щовечора</b><br>(1) Що сьогодні було найкращим? (2) Що здивувало або вразило? (3) Що хочу завтра зробити інакше?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пиши без редагування</b><br>Не думай про стиль. Це для тебе, не для оцінки. Навіть 2–3 речення — достатньо.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Малюй або клей</b><br>Якщо не хочеться писати — малюй настрій, клей фото, пиши одне слово. Формат — вільний.</div></div><div class=\"final-note\">💡 Щоденник вражень ≠ щоденник подій. «Сьогодні пішов до школи» — нецікаво. «Сьогодні зрозумів, що мені подобається малювати» — це щоденник вражень.</div>"],[90,"Дотримання режиму дня","<div class=\"rule-note\">🕐 <b>Режим дня</b> — це не обмеження, а паливо. Тіло і мозок працюють краще, коли знають що і коли. Хаотичний розпорядок = хронічна втома.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Три «якоря» дня: підйом, обід, відбій</b><br>Однаковий час щодня ±30 хвилин. Решта — підлаштується навколо них.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Шкільний блок: уроки + домашнє</b><br>Уроки → перерва 30–60 хв після школи → домашнє завдання → вільний час.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Вечір: без екранів за 1 год до сну</b><br>Телефон, комп'ютер, телевізор — стимулюють мозок. Книга, музика, розмова — заспокоюють.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Вихідні — режим ±1 год, не більше</b><br>Різкий зсув (лягти о 2, встати о 12) ламає ритм на 2–3 дні. «Соціальний джетлаг».</div></div><div class=\"final-note\">📌 Оптимальний режим: підйом 6:30–7:00, домашнє 15:00–17:30, вільний час 17:30–21:00, сон 21:30–22:00. Коригуй під себе, але тримай сталість.</div>"],[91,"Як звертатися по допомогу до вчителя","<div class=\"rule-note\">🙋 <b>Просити допомоги — це розумно, а не соромно.</b> Вчитель на уроці для того, щоб допомагати. Правильне звернення = швидка допомога.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>На уроці: підніми руку і чекай</b><br>Не кричи з місця. Підніми руку. Якщо вчитель зайнятий — почекай 1–2 хвилини.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Сформулюй запитання конкретно</b><br>НЕ «Я нічого не розумію» → «Я не розумію, як перейти від рядка 2 до рядка 3 у цьому прикладі.»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Після уроку: підійди особисто</b><br>«Можна запитати? Мені незрозуміло… Чи можете пояснити ще раз?» Вчителі цінують таких учнів.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Якщо соромно — запитай однокласника</b><br>Пояснення від ровесника часто зрозуміліше. Або знайди відповідь у підручнику сам — це теж навичка.</div></div><div class=\"final-note\">💡 Правило: незрозуміле сьогодні = проблема завтра. Нерозуміння накопичується. Одне запитання вчасно рятує годину зубріння перед контрольною.</div>"],[92,"Організація перерви між уроками","<div class=\"rule-note\">⏸️ <b>Перерва — не «нічогонероблення», а відновлення.</b> Правильна перерва збільшує продуктивність наступного уроку.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Перші 2 хвилини: підготуй матеріали до наступного уроку</b><br>Прибрав попереднє → дістав потрібне. Не витрачаєш час після дзвінка.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Рух — обов'язково</b><br>Встань, пройдись, потягнись. Мозок отримує кисень. Навіть 50 кроків коридором — помагає.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перекус — якщо довга перерва</b><br>Вода, фрукт, горіхи — підтримують концентрацію. НЕ чіпси та цукерки — різкий «цукровий крах» через 20 хвилин.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Телефон — помірно</b><br>Гортання стрічки — не відпочинок для мозку. Коротке повідомлення — так. 10 хвилин TikTok — ні.</div></div><div class=\"final-note\">📌 Ідеальна перерва: рух (2 хв) + їжа/вода (якщо треба) + коротке спілкування або свіже повітря. НЕ: сидіти за партою з телефоном.</div>"],[93,"Як боротися з неуважністю на уроці","<div class=\"rule-note\">🎯 <b>Неуважність</b> — це не лінь, а сигнал мозку. Три причини: втома, нецікаво, відволікачі. Три рішення відповідно.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Якщо втома: активізуй тіло</b><br>Стисни кулаки на 5 секунд і відпусти. Потягнись. Зроби 5 глибоких вдихів. Мозок «перезавантажиться».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Якщо нецікаво: знайди особистий зв'язок</b><br>Запитай себе: «Де я це використаю?» або «Як це пов'язано з тим, що мені важливо?»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Якщо відволікачі: усунь їх фізично</b><br>Телефон у портфель. Відсядь від друга. Пересядь ближче до дошки. Нотуй — навіть якщо зайве.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Метод «крапки»: фіксуй кожне відволікання</b><br>Відволікся → постав крапку в кутку зошита. Підрахуй наприкінці. Усвідомленість знижує кількість.</div></div><div class=\"final-note\">💡 Норма концентрації на уроці: 20–25 хвилин. Після цього мозок природно «відпливає». Це не проблема — це фізіологія. Допомагає: зміна виду діяльності на уроці.</div>"],[94,"Захист від цькування (булінгу)","<div class=\"rule-note\">🛡️ <b>Булінг — це не норма і не твоя провина.</b> Є чіткі дії, які змінюють ситуацію. Мовчати — найгірша стратегія.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розпізнай: це булінг, а не жарт</b><br>Булінг = повторюється + навмисне + одна сторона сильніша. Якщо тобі боляче — це не «просто жарт».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Не реагуй так, як очікує агресор</b><br>Плач, злість, відплата — це те, чого він хоче. Спокій і байдужість — найефективніша реакція.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Розкажи дорослому якнайшвидше</b><br>Батьки, класний керівник, шкільний психолог. Розповідь — не «ябедництво», а захист свого права.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Тримайся з друзями</b><br>Булінг рідко трапляється в групі. Знайди одного надійного союзника в класі.</div></div><div class=\"final-note\">📌 Запам'ятай: булер боїться наслідків і публічності. Якщо тобі чи комусь погрожують — фіксуй (скріншоти, дати, свідки). Це важливо для дорослих, які будуть допомагати.</div>"],[95,"Як поводитися при отриманні поганої оцінки","<div class=\"rule-note\">📉 <b>Погана оцінка — це не вирок, а зворотний зв'язок.</b> Те, як ти реагуєш на невдачу, важливіше за саму оцінку.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Не панікуй і не драматизуй</b><br>Одна «двійка» не руйнує рік. Дихай. Прийми факт: «Ок, це сталося. Що далі?»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Зрозумій причину</b><br>Не вивчив? Не зрозумів тему? Хвилювався? Був неуважний? Причина визначає рішення.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запитай вчителя що виправити</b><br>«Що мені потрібно зробити, щоб виправити оцінку?» — це зрілий підхід, який вчителі поважають.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Розкажи батькам сам</b><br>Краще ти — ніж вони дізнаються зі щоденника. «Я отримав погану оцінку. Ось чому. Ось що зроблю.»</div></div><div class=\"final-note\">💡 Правило: погана оцінка без аналізу = марна оцінка. Погана оцінка + аналіз + виправлення = навчання. Найуспішніші люди провалювались частіше за середніх — але вставали.</div>"],[96,"Правильне харчування у школі","<div class=\"rule-note\">🥗 <b>Мозок — 2% ваги тіла, але споживає 20% енергії.</b> Те, що їси, прямо впливає на концентрацію, пам'ять і настрій.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Сніданок — обов'язково</b><br>Мозок після сну «порожній». Без сніданку — знижена увага з першого уроку. Навіть банан + склянка молока.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перекус у школі</b><br>Фрукти, горіхи, йогурт, бутерброд з сиром. Уникай: чіпсів, газованого, шоколадних батончиків — різкий стрибок і падіння енергії.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Вода — постійно</b><br>Навіть помірне зневоднення (2% маси тіла) помітно знижує увагу та здатність зосередитись — це підтверджено дослідженнями. Пий воду між уроками, а не лише коли хочеться.</div></div><div class=\"final-note\">📌 «Правило тарілки» для мозку: складні вуглеводи (хліб, крупи) — стабільна енергія. Білок (яйця, м'ясо, горіхи) — будівельний матеріал нейронів. Овочі/фрукти — вітаміни для пам'яті.</div>"],[97,"Як налагодити стосунки з однокласниками","<div class=\"rule-note\">😊 <b>Добрі стосунки з однокласниками</b> роблять школу приємнішою і навчання легшим. Навичка побудови стосунків важлива все життя.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Почни з малого: привітайся першим</b><br>«Привіт!» + усмішка — найпростіший початок. Роби це щодня, навіть якщо відповідь невиразна.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Знайди спільне</b><br>Запитай: «Що слухаєш? Яку гру граєш? Дивився цей фільм?» Спільне = база для розмови.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Допомагай, не розраховуючи на відповідь</b><br>Позичи ручку, поясни завдання, підтримай — щиро, без рахунку. Репутація доброї людини будується роками.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Не пліткуй і не обговорюй заочно</b><br>Плітки завжди повертаються. Якщо не скажеш нічого поганого — не матимеш ворогів.</div></div><div class=\"final-note\">💡 Не треба дружити з усіма — треба поважати всіх. 1–2 справжніх друзі кращі за 20 «знайомих». Якість стосунків важливіша за кількість.</div>"],[98,"Дотримання правил безпеки в школі","<div class=\"rule-note\">⚠️ <b>Безпека в школі</b> — знати правила і діяти автоматично. Небезпечні ситуації рідкісні, але готовність важлива.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Знай де евакуаційні виходи</b><br>У кожному класі і на кожному поверсі. 30 секунд — і ти знаєш план евакуації.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Не бігай на перервах у коридорах</b><br>Більшість травм — не бійки, а необережний біг і штовханина. Уповільнись у коридорі.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Знай де аптечка і медпункт</b><br>Пройшовся школою — запам'ятав. При порізі чи пошкодженні — відразу до медпункту.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Не мовчи про небезпечні ситуації</b><br>Знайшов підозрілий предмет, бачив загрозу — одразу до вчителя або охоронця. Мовчання ≠ безпека.</div></div><div class=\"final-note\">📌 Алгоритм у надзвичайній ситуації: (1) Не панікуй. (2) Повідом дорослого. (3) Слідуй інструкціям. (4) Залишайся зі своєю групою. Запам'ятай і не забудь.</div>"],[99,"Як розвинути самостійність у навчанні","<div class=\"rule-note\">🌱 <b>Самостійність у навчанні</b> — уміння вчитися без постійного нагадування. Це головна навичка для університету і дорослого життя.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Плануй домашнє завдання сам</b><br>Відкрив щоденник → склав список → виконав → перевірив. Без нагадувань батьків.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Шукай відповіді самостійно спочатку</b><br>Незрозуміле слово → спочатку словник, потім підручник, потім — запитання. Не одразу «мамо, що таке…?»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Контролюй свій прогрес</b><br>Раз на тиждень: які оцінки? Що покращилось? Що потрібно підтягнути? Веди в зошиті або телефоні.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Встановлюй власні цілі</b><br>НЕ «мама сказала вивчити» → «Я хочу зрозуміти цю тему, бо вона знадобиться». Внутрішня мотивація сильніша.</div></div><div class=\"final-note\">💡 Тест самостійності: «Якби завтра не було уроку — я б усе одно повторив цей матеріал?» Якщо так — ти вже самостійний учень. Якщо ні — шукай особистий інтерес до теми.</div>"],[100,"Підготовка до шкільних екскурсій та заходів","<div class=\"rule-note\">🎒 <b>Підготовлений учень</b> отримує від екскурсії максимум, а не стоїть з порожніми руками.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>За день: дізнайся деталі</b><br>Куди їдемо? О котрій збір? Що потрібно взяти? Запитай у вчителя або прочитай оголошення.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Підготуй рюкзак</b><br>Вода. Перекус. Зручне взуття. Дощовик якщо треба. Телефон заряджений. Гроші якщо дозволено.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>На заході: будь присутнім</b><br>Поклади телефон. Дивись, слухай, запитуй. Одна фотографія «на пам'ять» — ок. 50 — ні.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Після: зафіксуй враження</b><br>Запиши 3 нових факти або враження. Це і є реальне навчання поза класом.</div></div><div class=\"final-note\">📌 Екскурсія — не прогулянка, а урок поза класом. Учні, які слухають і запитують, отримують додаткові бали та довіру вчителя.</div>"],[101,"Фінальна саморефлексія дня","<div class=\"rule-note\">🌙 <b>Саморефлексія</b> — 5 хвилин ввечері, які роблять кожен наступний день кращим за попередній. Найуспішніші люди практикують це щодня.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запитання 1: «Що сьогодні вдалося?»</b><br>Знайди хоча б одне — навіть маленьке. Мозок, що помічає успіхи, мотивований більше.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Запитання 2: «Що було складним?»</b><br>Без самозвинувачення. Просто факт: «Я не зрозумів нову тему з математики».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Запитання 3: «Що зроблю інакше завтра?»</b><br>Одне конкретне рішення: «Завтра запишу домашнє відразу на уроці».</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Запитання 4: «За що я вдячний сьогодні?»</b><br>Вдячність знижує тривогу і покращує сон. 1–2 речі — достатньо.</div></div><div class=\"final-note\">✨ Запиши відповіді у щоденник або просто обміркуй подумки. 5 хвилин рефлексії = 5 кроків до кращої версії себе. Це не підручникова теорія — це практика лідерів і чемпіонів.</div>"]]},
    {"n":"💻 Програмування та алгоритмічне мислення","e":"","cards": [
        [2027,"Що таке алгоритм: властивості та приклади","<div class=\"rule-note\">Алгоритм — точна і зрозуміла послідовність кроків для розв'язання задачі. Термін походить від імені математика IX&nbsp;ст. аль-Хорезмі (algorithmi — латинізована форма). Поняття алгоритму є фундаментальним в інформатиці.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Дискретність</b> — алгоритм складається з окремих, чітко відмежованих кроків, що виконуються послідовно.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Визначеність</b> — кожен крок однозначний: виконавець не може трактувати його по-різному.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Скінченність</b> — алгоритм завжди завершується після кінцевої кількості кроків.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Масовість</b> — один алгоритм розв'язує цілий клас однотипних задач (рецепт хліба — для будь-якого тіста).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Результативність</b> — після виконання алгоритму отримуємо конкретний результат або повідомлення, що задача не має розв'язку.</span></div><div class=\"final-note\">Рецепт страви, інструкція з монтажу, маршрут навігатора — все це алгоритми у повсякденному житті.</div>"],
        [2028,"Типи даних у програмуванні: int, float, str, bool","<div class=\"rule-note\">Тип даних визначає, яку інформацію зберігає змінна і які операції над нею можливі. Базові типи є в усіх мовах програмування.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>int (ціле число)</b> — зберігає цілі числа без дробової частини: -5, 0, 42, 1000. У Python int не має фіксованого ліміту розміру.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>float (дробове число)</b> — числа з плаваючою точкою: 3.14, -0.5, 2.0. Зберігаються у двійковому форматі, тому можливі дрібні похибки (0.1&nbsp;+&nbsp;0.2&nbsp;≠&nbsp;0.3 точно).</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>str (рядок)</b> — послідовність символів у лапках: \"Привіт\", '123'. Навіть \"5\" — це рядок, а не число.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>bool (логічний)</b> — лише два значення: True або False. Основа всіх умов: if, while, логічних виразів. 0 і порожній рядок \"\" — хибні; 1 і непорожній рядок — істинні.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Перетворення типів</b> — int(\"42\") → 42; str(100) → \"100\"; float(3) → 3.0. Не всі перетворення можливі: int(\"hello\") — помилка.</span></div><div class=\"final-note\">Розуміння типів даних — перший крок до написання коду без непередбачуваних помилок.</div>"],
        [2029,"Змінні та константи: як зберігати дані в програмі","<div class=\"rule-note\">Змінна — іменована область пам'яті, де зберігається значення, яке може змінюватися. Константа — значення, яке не змінюється під час виконання програми.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Оголошення змінної</b> — у Python просто: age = 25. У мовах зі статичною типізацією (Java, C++) тип вказується явно: int age = 25;</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Правила іменування</b> — починається з літери або підкреслення, містить лише літери, цифри та _. Регістр важливий: name ≠ Name. Не використовуйте зарезервовані слова (if, for, while).</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Стиль іменування</b> — snake_case для Python (user_name), camelCase для Java/JS (userName). Назви мають відображати зміст: age, not x1.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Константи</b> — у Python позначаються ВЕЛИКИМИ_ЛІТЕРАМИ: MAX_SIZE = 100. Це угода, а не заборона: мова не забороняє їх змінювати, але це сигнал для розробників.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Область видимості</b> — локальна змінна існує лише всередині функції; глобальна — доступна з усього файлу. Уникайте надмірного використання глобальних змінних.</span></div><div class=\"final-note\">Чітке іменування змінних — це ввічливість до майбутнього себе і до колег.</div>"],
        [2030,"Умовний оператор if-else: логіка розгалуження","<div class=\"rule-note\">Умовний оператор if-else дозволяє програмі «приймати рішення» — виконувати різний код залежно від умови. Основа будь-якої нетривіальної логіки.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Проста форма (if)</b> — виконується блок, якщо умова True.<br><code>if temperature &gt; 30:<br>&nbsp;&nbsp;&nbsp;&nbsp;print(\"Спекотно\")</code></span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Повна форма (if-else)</b> — два шляхи виконання.<br><code>if score &gt;= 60:<br>&nbsp;&nbsp;&nbsp;&nbsp;print(\"Здав\")<br>else:<br>&nbsp;&nbsp;&nbsp;&nbsp;print(\"Не здав\")</code></span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Кілька умов (elif)</b> — перевіряються по черзі, виконується перша істинна.<br><code>if score &gt;= 90: print(\"A\")<br>elif score &gt;= 75: print(\"B\")<br>else: print(\"C\")</code></span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Логічні оператори в умовах</b> — and (обидві умови), or (хоча б одна), not (заперечення): <code>if age &gt;= 18 and has_id:</code></span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Вкладені умови</b> — if всередині if можливий, але глибоке вкладення знижує читабельність. Якщо вкладень більше 3 — варто розбити на функції.</span></div><div class=\"final-note\">Розгалуження — це мова, якою програма розмовляє з реальністю: «якщо так — роблю це, інакше — те».</div>"],
        [2031,"Цикли: for та while — коли і як використовувати","<div class=\"rule-note\">Цикл — це повторення блоку коду. Без циклів програміст мав би писати одну й ту саму дію тисячі разів вручну.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Цикл for</b> — для перебору відомої кількості елементів або заданого діапазону.<br><code>for i in range(5):<br>&nbsp;&nbsp;&nbsp;&nbsp;print(i)  # 0,1,2,3,4</code></span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Цикл while</b> — повторюється, поки умова True. Використовується, коли кількість ітерацій заздалегідь невідома.<br><code>while balance &gt; 0:<br>&nbsp;&nbsp;&nbsp;&nbsp;balance -= payment</code></span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>break та continue</b> — break перериває цикл повністю; continue пропускає поточну ітерацію і переходить до наступної.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Нескінченний цикл</b> — while True: — виходять через break. Корисний для меню, серверів, очікування подій. Небезпечний без умови виходу.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Коли що обирати</b> — for: перебір списку, рядка, діапазону. while: очікування умови, читання потоку, гра з ходами. Уникайте while там, де for достатній.</span></div><div class=\"final-note\">Цикл — головний інструмент автоматизації: комп'ютер не стомлюється від повторень.</div>"],
        [2032,"Функції у програмуванні: навіщо і як","<div class=\"rule-note\">Функція — іменований блок коду, що виконує одну конкретну задачу. Дозволяє уникнути дублювання коду і структурувати програму.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Оголошення функції</b> (Python):<br><code>def greet(name):<br>&nbsp;&nbsp;&nbsp;&nbsp;return \"Привіт, \" + name</code><br>Виклик: greet(\"Олено\") → \"Привіт, Олено\"</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Параметри та аргументи</b> — параметри — це змінні у визначенні функції (name). Аргументи — конкретні значення при виклику (\"Олено\").</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>return</b> — функція повертає результат. Без return повертає None. Функція завершується при першому return.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Принцип єдиної відповідальності</b> — одна функція робить одну річ. Якщо назва функції contains \"і\" (рахує і виводить і записує) — розбийте на кілька.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Значення за замовчуванням</b> — <code>def greet(name=\"Гостю\"):</code> — параметр необов'язковий. Якщо аргумент не переданий — використовується значення за замовчуванням.</span></div><div class=\"final-note\">Добра функція — це та, яку можна зрозуміти, прочитавши лише її назву.</div>"],
        [2033,"Масиви та списки: зберігаємо набір даних","<div class=\"rule-note\">Список (list у Python, array у більшості мов) — впорядкована колекція елементів. Дозволяє зберігати багато значень під одним іменем.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Створення списку</b> (Python): <code>fruits = [\"яблуко\", \"груша\", \"слива\"]</code>. Список може містити елементи різних типів, включаючи інші списки.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Доступ за індексом</b> — індексація з нуля: fruits[0] → \"яблуко\", fruits[-1] → \"слива\" (останній). Вихід за межі → IndexError.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Основні операції</b> — append(x) додає в кінець; insert(i, x) вставляє на позицію; remove(x) видаляє перше входження; pop() видаляє і повертає останній елемент.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Перебір списку</b> — <code>for fruit in fruits: print(fruit)</code>. З індексом: <code>for i, fruit in enumerate(fruits):</code></span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Зрізи (slices)</b> — fruits[1:3] → [\"груша\", \"слива\"]; fruits[:2] → перші два; fruits[::2] → кожен другий. Не змінює оригінал.</span></div><div class=\"final-note\">Список — найбільш вживана структура даних у Python. Розуміння зрізів і методів — базова навичка.</div>"],
        [2034,"Блок-схеми: як зображати алгоритм графічно","<div class=\"rule-note\">Блок-схема — графічне зображення алгоритму за допомогою стандартних символів. Допомагає спроектувати логіку перед написанням коду.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Основні символи</b> — овал/еліпс: початок і кінець; прямокутник: дія (обчислення, присвоєння); ромб: умова (рішення); паралелограм: введення/виведення; стрілка: напрямок виконання.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Розгалуження у блок-схемі</b> — з ромба виходять дві стрілки: «Так» (Yes/True) і «Ні» (No/False). Позначаються явно.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Цикл у блок-схемі</b> — умова перевіряється у ромбі; одна стрілка веде до тіла циклу, потім назад до ромба; друга — виходить з циклу.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Правила читабельності</b> — блок-схема читається зверху вниз; стрілки не перетинаються без потреби; кожен блок підписується коротко і зрозуміло.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Інструменти</b> — draw.io (безкоштовно, онлайн), Lucidchart, Miro. Для простих схем — папір і олівець на етапі планування.</span></div><div class=\"final-note\">Блок-схема — це карта перед подорожжю кодом. Намалюй логіку — і помилок буде менше.</div>"],
        [2035,"Відлагодження коду (debugging): пошук і виправлення помилок","<div class=\"rule-note\">Debugging (відлагодження) — процес пошуку і виправлення помилок у коді. Навичка налагодження важливіша, ніж написання без помилок — помилки є у кожного.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Типи помилок</b> — SyntaxError: неправильний синтаксис (пропущена дужка); RuntimeError: виникає під час виконання (ділення на нуль); LogicError: код працює, але дає неправильний результат.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>print-відлагодження</b> — найпростіший метод: додайте print() у підозрілі місця, щоб побачити значення змінних у момент виконання.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Дебагер (debugger)</b> — вбудований в IDE (VS Code, PyCharm): дозволяє зупинити виконання на breakpoint і крок за кроком переглянути стан програми.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Метод «качки»</b> (rubber duck debugging) — поясніть код уголос, ніби пояснюєте іграшковій качці. Часто помилка знаходиться в момент пояснення. Метод описаний у «The Pragmatic Programmer» (Hunt, Thomas, 1999).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Читання трейсу помилки</b> — Python виводить Traceback: читайте знизу вгору. Останній рядок — тип і суть помилки; вище — місце в коді.</span></div><div class=\"final-note\">Відлагодження — не ознака невміння. Це частина процесу. Навіть досвідчені розробники витрачають значну частину часу на налагодження.</div>"],
        [2036,"Сортування: як впорядкувати дані","<div class=\"rule-note\">Сортування — одна з базових задач програмування. Розуміння принципів допомагає обирати правильний підхід залежно від розміру та характеру даних.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Bubble sort (сортування бульбашкою)</b> — порівнюємо сусідні елементи і міняємо місцями, якщо вони не в порядку. Простий для розуміння, але повільний для великих масивів — O(n²).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Selection sort (вибором)</b> — знаходимо мінімум і ставимо на початок, потім мінімум з решти і т.д. Так само O(n²), але менше обмінів.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Quick sort та Merge sort</b> — ефективніші алгоритми зі складністю O(n·log n) у середньому. Вбудоване сортування Python (Timsort) засноване на merge sort.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Вбудоване сортування Python</b> — sorted(list) повертає новий відсортований список; list.sort() сортує на місці. Параметр key= задає критерій: sorted(words, key=len) — за довжиною.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Коли алгоритм важливий</b> — для малих масивів (до 1000 елементів) різниця несуттєва. Для великих даних — вибір алгоритму критично впливає на швидкість.</span></div><div class=\"final-note\">Розуміння хоча б bubble sort розкриває суть ефективності: чому один код швидший за інший.</div>"],
        [2037,"Двійкова система числення: як комп'ютер рахує","<div class=\"rule-note\">Комп'ютер зберігає і обробляє дані у двійковій (бінарній) системі числення, де є лише два символи: 0 і 1. Це пов'язано з фізичною природою транзистора — відкритий/закритий.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Позиційна система</b> — у десятковій позиція означає ступінь 10 (234 = 2·10²+3·10¹+4·10⁰). У двійковій — ступінь 2: 1101₂ = 1·8+1·4+0·2+1·1 = 13₁₀.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Переведення десяткового у двійкове</b> — ділимо на 2, записуємо залишки знизу вгору: 13 → 6 залишок 1 → 3 залишок 0 → 1 залишок 1 → 0 залишок 1. Результат: 1101.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Біт і байт</b> — 1 біт = один символ 0 або 1. 1 байт = 8 біт. 1 байт може кодувати 2⁸ = 256 різних значень. Кілобайт (КБ) = 1024 байти.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Шістнадцяткова система (hex)</b> — цифри 0–9 і A–F. Використовується для компактного запису бінарних даних: один hex-символ = 4 біти. FF₁₆ = 11111111₂ = 255₁₀.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Python і системи числення</b> — bin(13) → &#39;0b1101&#39;; hex(255) → &#39;0xff&#39;; int(&#39;1101&#39;, 2) → 13; int(&#39;ff&#39;, 16) → 255.</span></div><div class=\"final-note\">Двійкова система — мова машини. Розуміння її допомагає зрозуміти, чому є обмеження типів, кодування символів і кольорів.</div>"],
        [2038,"Рекурсія: функція, що викликає саму себе","<div class=\"rule-note\">Рекурсія — прийом програмування, коли функція викликає сама себе для розв'язання підзадачі. Елегантна, але вимагає розуміння базового випадку.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Обов'язкові складові</b> — базовий випадок (умова виходу) + рекурсивний виклик. Без базового випадку — нескінченна рекурсія і помилка RecursionError.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Класичний приклад — факторіал</b>:<br><code>def factorial(n):<br>&nbsp;&nbsp;&nbsp;&nbsp;if n == 0: return 1  # базовий<br>&nbsp;&nbsp;&nbsp;&nbsp;return n * factorial(n-1)  # рекурсія</code></span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Як думати рекурсивно</b> — уявіть, що функція вже працює для n-1. Вам залишилось лише виразити відповідь для n через відповідь для n-1.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Стек викликів</b> — кожен рекурсивний виклик додає запис у стек. При n=1000 стек переповниться. Ліміт рекурсії у Python за замовчуванням — 1000 рівнів.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Коли рекурсія доцільна</b> — обхід дерев, пошук у файловій системі, алгоритми «розділяй та володарюй». Для простих задач (цикл) — краще ітерація.</span></div><div class=\"final-note\">Рекурсія навчає мислити на рівень абстракції вище. Коли зрозумів рекурсію — зрозумів ключовий принцип програмування.</div>"],
        [2039,"Основи Python: перша програма і базовий синтаксис","<div class=\"rule-note\">Python — мова програмування загального призначення, розроблена Гвідо ван Россумом (перша версія 1991&nbsp;р.). Відзначається читабельним синтаксисом і широким застосуванням: від автоматизації до машинного навчання.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Перша програма</b> — <code>print(\"Привіт, Світе!\")</code>. Запуск: python3 hello.py у терміналі або кнопка Run в IDE. IDLE та VS Code — популярні середовища для початківців.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Відступи — це синтаксис</b> — у Python відступи (як правило, 4 пробіли) визначають структуру коду. Неправильний відступ — IndentationError.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Коментарі</b> — рядок після # ігнорується інтерпретатором: <code># це коментар</code>. Коментуйте «чому», а не «що» — код описує «що» сам.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Введення даних</b> — <code>name = input(\"Як тебе звати? \")</code>. input() завжди повертає рядок. Для числа: <code>age = int(input(\"Вік: \"))</code>.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>f-рядки для виводу</b> — <code>print(f\"Привіт, {name}! Тобі {age} р.\")</code> — зручний спосіб вставляти змінні у текст (доступний з Python 3.6).</span></div><div class=\"final-note\">Python навмисно спроектований як мова, яку легко читати. Якщо код виглядає заплутано — його варто переписати.</div>"],
        [2040,"Операції з рядками (string): основні прийоми","<div class=\"rule-note\">Рядок (string) — послідовність символів. Маніпуляції з рядками є базовою навичкою: обробка тексту, парсинг даних, форматування виводу.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Конкатенація і повторення</b> — \"Привіт\" + \" \" + \"Світе\" → \"Привіт Світе\". \"Ha\" * 3 → \"HaHaHa\". Не можна додавати str і int: \"5\" + 3 → TypeError.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Методи рядка</b> — upper()/lower() — регістр; strip() — прибрати пробіли на краях; replace(a, b) — замінити; split(sep) — розбити на список; join(list) — зібрати зі списку.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Пошук у рядку</b> — \"світ\" in \"Привіт Світе\" → True (з урахуванням регістру). find(sub) → індекс першого входження або -1. count(sub) → кількість входжень.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Зрізи рядка</b> — s = \"Привіт\"; s[0] → \"П\"; s[-1] → \"т\"; s[2:5] → \"иві\"; s[::-1] → рядок навпаки. Рядки незмінні: s[0] = \"п\" → TypeError.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Перевірка вмісту</b> — isdigit() → лише цифри; isalpha() → лише літери; startswith()/endswith() → починається/закінчується на підрядок.</span></div><div class=\"final-note\">Уміння ефективно працювати з рядками заощаджує години роботи з текстовими даними.</div>"],
        [2041,"Словники (dict) у Python: структура ключ-значення","<div class=\"rule-note\">Словник (dict) — структура даних, де кожне значення зберігається під унікальним ключем. Аналог реального словника: слово (ключ) → визначення (значення).</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Створення словника</b> — <code>person = {\"name\": \"Олена\", \"age\": 30, \"city\": \"Київ\"}</code>. Ключі — зазвичай рядки або числа; значення — будь-який тип.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Доступ та зміна</b> — person[\"name\"] → \"Олена\". person[\"age\"] = 31 — змінює значення. person[\"email\"] = \"...\" — додає нову пару. Доступ до відсутнього ключа → KeyError.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Безпечний доступ</b> — person.get(\"phone\") → None (без помилки). person.get(\"phone\", \"не вказано\") → значення за замовчуванням.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Перебір словника</b> — for key in person: → ключі; for key, value in person.items(): → пари ключ-значення; person.keys(); person.values().</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Коли використовувати dict</b> — коли дані мають назви (атрибути об'єкта), коли потрібен швидкий пошук за ключем, для підрахунку частот: word_count = {}.</span></div><div class=\"final-note\">Словники — один з найпотужніших інструментів Python. JSON (формат обміну даними в інтернеті) — це, по суті, словник.</div>"],
        [2042,"Файли у програмуванні: читання і запис","<div class=\"rule-note\">Робота з файлами дозволяє програмі зберігати дані між запусками і обмінюватися даними з іншими програмами. Базова навичка для будь-якого прикладного програмування.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Відкриття файлу</b> — <code>f = open(\"file.txt\", \"r\", encoding=\"utf-8\")</code>. Режими: \"r\" — читання, \"w\" — запис (стирає вміст), \"a\" — дозапис, \"rb\"/\"wb\" — бінарний режим.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Контекстний менеджер (with)</b> — правильний спосіб роботи з файлами:<br><code>with open(\"file.txt\") as f:<br>&nbsp;&nbsp;&nbsp;&nbsp;text = f.read()</code><br>Файл закривається автоматично навіть при помилці.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Читання рядків</b> — f.read() → весь файл рядком; f.readlines() → список рядків; for line in f: → поелементний перебір без завантаження всього файлу в пам'ять.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Запис у файл</b> — <code>with open(\"out.txt\", \"w\", encoding=\"utf-8\") as f:<br>&nbsp;&nbsp;&nbsp;&nbsp;f.write(\"Текст\n\")</code>. \n — символ нового рядка.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>CSV та JSON</b> — структуровані текстові формати для даних. Python має вбудовані модулі csv і json: import json; data = json.load(f) читає JSON-файл у словник.</span></div><div class=\"final-note\">Уміння читати і писати файли відкриває роботу з реальними даними: логами, таблицями, налаштуваннями.</div>"],
        [2043,"ООП: клас та об'єкт — базові поняття","<div class=\"rule-note\">Об'єктно-орієнтоване програмування (ООП) — парадигма, де код організовано навколо об'єктів, які містять дані (атрибути) і поведінку (методи).</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Клас — це шаблон</b> — клас описує структуру, об'єкт — конкретний екземпляр. Аналогія: клас — це креслення будинку, об'єкт — конкретний збудований будинок.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Визначення класу (Python)</b>:<br><code>class Dog:<br>&nbsp;&nbsp;&nbsp;&nbsp;def __init__(self, name):<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;self.name = name<br>&nbsp;&nbsp;&nbsp;&nbsp;def bark(self):<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return self.name + \" гавкає\"</code></span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Створення об'єкту</b> — <code>my_dog = Dog(\"Рекс\")</code>. __init__ — конструктор, викликається автоматично. self — посилання на конкретний об'єкт.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Три стовпи ООП</b> — інкапсуляція (дані всередині об'єкту); успадкування (клас-нащадок отримує властивості батька); поліморфізм (різні об'єкти реагують на один виклик по-своєму).</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Коли ООП доцільне</b> — для складних програм з багатьма взаємодіючими сутностями. Для простих скриптів процедурний підхід зручніший. Не застосовуйте ООП заради ООП.</span></div><div class=\"final-note\">ООП — не срібна куля, а один зі стилів мислення. Розуміння класів відкриває роботу з бібліотеками та фреймворками.</div>"],
        [2044,"Алгоритмічне мислення: як розбити задачу на кроки","<div class=\"rule-note\">Алгоритмічне мислення — здатність розкладати задачу на чіткі, логічно пов'язані кроки, які може виконати виконавець. Це навичка, а не вроджена риса — вона розвивається практикою.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Декомпозиція</b> — розбийте велику задачу на менші підзадачі. «Зробити сайт» → верстка, логіка, база даних, деплой. Кожна підзадача вирішується окремо.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Розпізнавання патернів</b> — знаходьте спільне між задачами. Задача про сортування іспитових балів — той самий алгоритм, що для сортування товарів. Не винаходьте колесо.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Абстракція</b> — ігноруйте несуттєві деталі. «Як водій проїхати по місту» — не важливо, яка марка авто і колір світлофора. Важливий маршрут.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Перевірка алгоритму</b> — простежте виконання вручну на конкретному прикладі (trace). Чи дає алгоритм правильний результат? Чи зупиняється він?</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Як тренувати</b> — розв'язуйте логічні задачі (сайти Codewars, LeetCode для новачків), пишіть алгоритми для побутових задач, пояснюйте свій розв'язок вголос.</span></div><div class=\"final-note\">Алгоритмічне мислення застосовується не лише в програмуванні — будь-яка системна задача вирішується краще з чітким алгоритмом.</div>"],
        [2045,"Git та контроль версій: основи для початківців","<div class=\"rule-note\">Git — система контролю версій, створена Лінусом Торвальдсом у 2005&nbsp;р. для розробки ядра Linux. Дозволяє зберігати всю історію змін коду і повертатися до будь-якої версії.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Три стани файлу</b> — Working Directory (ваші зміни); Staging Area (підготовлені до збереження); Repository (збережена знімок — commit).</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>Базові команди</b> — git init: ініціалізація репозиторію. git add file.py: додати у staging. git commit -m \"Опис змін\": зберегти знімок. git status: стан файлів. git log: історія комітів.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>Гілки (branches)</b> — git branch feature-auth: створити гілку. git checkout feature-auth: перейти. git merge feature-auth: злити в основну. Гілки дозволяють паралельно розробляти функції.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>GitHub / GitLab</b> — хмарне сховище для репозиторіїв. git push — відвантажити зміни у хмару; git pull — отримати зміни від інших.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Правило добрих комітів</b> — один коміт = одна логічна зміна. Опис: дієслово + що зроблено: \"Add login form validation\". Уникайте \"fix\", \"update\", \"changes\" без деталей.</span></div><div class=\"final-note\">Git — стандарт галузі. Відсутність контролю версій — це ризик втратити роботу і не змогти відновити попередній стан.</div>"],
        [2046,"Вибір мови програмування: Python, JavaScript, C++","<div class=\"rule-note\">Вибір першої мови програмування менш важливий, ніж розуміння концепцій. Базові ідеї (змінні, цикли, функції) однакові у всіх мовах. Але контекст вибору має значення.</div><div class=\"step c1\"><span class=\"step-num\">1</span><span class=\"step-text\"><b>Python</b> — рекомендується для початківців, науки про дані, автоматизації, машинного навчання. Мінімальний синтаксичний шум. Велика спільнота. Не найшвидша у виконанні.</span></div><div class=\"step c2\"><span class=\"step-num\">2</span><span class=\"step-text\"><b>JavaScript</b> — єдина мова, яку розуміє браузер нативно. Обов'язкова для веб-розробки (frontend). З Node.js — і для backend. Асинхронна природа потребує звикання.</span></div><div class=\"step c3\"><span class=\"step-num\">3</span><span class=\"step-text\"><b>C++ / C</b> — системне програмування, ігри (Unreal Engine), вбудовані системи. Максимальна продуктивність. Складніший для початківця: ручне управління пам'яттю.</span></div><div class=\"step c4\"><span class=\"step-num\">4</span><span class=\"step-text\"><b>Java / Kotlin</b> — корпоративний backend, Android-розробка. Строга типізація, велика кількість готових бібліотек. Kotlin поступово витісняє Java в Android.</span></div><div class=\"step c1\"><span class=\"step-num\">5</span><span class=\"step-text\"><b>Правило вибору</b> — обирайте мову під задачу і під ринок праці у вашому регіоні. Якщо мета — швидко почати: Python. Веб — JavaScript. Не вивчайте мову «про запас» без конкретного проекту.</span></div><div class=\"final-note\">Перша мова — не вирок. Більшість розробників знають 3–5 мов. Навчившись одній, другу освоїти значно легше.</div>"]
      ]
    }]};
if(window.__catLoaded)window.__catLoaded(1,CAT_1);